@pytest.mark.asyncio
async def test_agent_claim_refreshes_only_current_strategic_policy(
    client: AsyncClient, db_session
):
    """Queued Strategic work gets claim-time policy without rewriting provenance."""
    from app.release_qualifier import _runtime_config

    project = Project(name="Strategic Claim Policy", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    stale_current = {
        "threshold": 0.90,
        "weights": {"audit": 0.6, "test_erosion": 0.4},
        "source": "runtime_config",
        "fallback_error": None,
        "policy_hash": "stale-current-policy",
    }
    frozen_attempt = {
        "threshold": 0.90,
        "weights": {"audit": 0.6, "test_erosion": 0.4},
        "source": "runtime_config",
        "fallback_error": None,
        "policy_hash": "frozen-attempt-policy",
    }
    task = Task(
        project_id=project.id,
        payloads=[
            {
                "type": "strategic_review",
                "current_effective_policy": stale_current,
                "active_or_last_attempt_policy": frozen_attempt,
                "version_phase": {
                    "phase": "stabilize",
                    "current_effective_policy": stale_current,
                    "active_or_last_attempt_policy": frozen_attempt,
                },
            }
        ],
        vm_instance_id="agent-vm-strategic-policy",
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-strategic-policy")
    with patch.dict(
        _runtime_config,
        {
            "promotion_threshold": 0.81,
            "promotion_weights": {"audit": 0.6, "test_erosion": 0.4},
        },
        clear=False,
    ):
        response = await client.post(
            "/api/agent/claim", headers={"x-agent-token": token}
        )

    assert response.status_code == 200, response.text
    claimed = response.json()["payloads"][0]
    assert claimed["current_effective_policy"]["threshold"] == pytest.approx(0.81)
    assert claimed["current_effective_policy"]["source"] == "runtime_config"
    assert claimed["version_phase"]["current_effective_policy"] == claimed[
        "current_effective_policy"
    ]
    assert claimed["active_or_last_attempt_policy"] == frozen_attempt
    assert (
        claimed["version_phase"]["active_or_last_attempt_policy"]
        == frozen_attempt
    )

    await db_session.refresh(task)
    stored = task.first_payload
    assert stored["current_effective_policy"] == stale_current
    assert stored["version_phase"]["current_effective_policy"] == stale_current
    assert stored["active_or_last_attempt_policy"] == frozen_attempt


@pytest.mark.smoketest
@pytest.mark.asyncio
async def test_agent_status_update(client: AsyncClient, db_session, mocker):
    """
    Tests an agent updating task status and creating an artifact.
    Also verifies that completing the last task does NOT flip the project's
    (deprecated) lifecycle status — the finite-project all-terminal aggregation
    was removed, so project.status stays untouched by task completion.
    """
    # VM deletion on task completion now uses fire_and_forget_vm_delete (a
    # non-awaited background task) to avoid holding the DB FOR UPDATE lock
    # through GCP I/O. Patch at the vm_lifecycle level so the assertion
    # captures the synchronous call rather than racing a background asyncio task.
    mock_fire_forget = mocker.patch("app.vm_lifecycle.fire_and_forget_vm_delete")

    # Project.status is a deprecated legacy field; task completion no longer
    # aggregates it to a terminal status (the all-terminal aggregation was
    # removed). The project's status must stay at its default after the last
    # task completes.
    project = Project(
        name="Agent Status Test",
        user_id="test-user-123",
        autonomous_enabled=False,
    )
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "ls"}],
        vm_instance_id="agent-vm-888",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-888")
    headers = {"x-agent-token": token}
    payload = {
        "task_id": str(task.id),
        "status": "COMPLETED",
        "artifact_type": "ERROR_LOG",
        "logs": "build success",
    }
    resp = await client.post("/api/agent/status", json=payload, headers=headers)
    assert resp.status_code == 200

    await db_session.refresh(task)
    assert task.status == TaskStatus.COMPLETED

    await db_session.refresh(project)
    # Aggregation removed: completing the last task leaves project.status at its
    # creation default (DRAFT) rather than flipping it to COMPLETED.
    assert project.status == ProjectStatus.DRAFT

    mock_fire_forget.assert_called_once_with("agent-vm-888", reason="agent_completion")


@pytest.mark.asyncio
async def test_agent_status_update_persists_runtime_identity(
    client: AsyncClient, db_session, mocker
):
    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    now = _utcnow()

    project = Project(name="Agent Runtime Identity Test", user_id="test-user-123")
    account = MaxPlanAccount(
        user_id="test-user-123",
        name="runtime-openai-account",
        provider=LLMProviderName.OPENAI,
        auth_mode=LLMAuthMode.API_KEY,
    )
    db_session.add(project)
    db_session.add(account)
    await db_session.commit()
    await db_session.refresh(project)
    await db_session.refresh(account)

    account_id = str(account.id)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        vm_instance_id="agent-vm-runtime",
        status=TaskStatus.IN_PROGRESS,
        vm_provisioned_at=now - timedelta(minutes=5),
        context={
            "llm_account_id": account_id,
            "max_plan_account_id": account_id,
        },
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-runtime")
    headers = {"x-agent-token": token}
    payload = {
        "task_id": str(task.id),
        "status": "COMPLETED",
        "artifact_type": "ERROR_LOG",
        "logs": "provider-specific failure",
        "provider": "openai",
        "auth_mode": "api_key",
        "model": "gpt-5.4",
        "execution_mode": "default",
    }
    resp = await client.post("/api/agent/status", json=payload, headers=headers)
    assert resp.status_code == 200

    await db_session.refresh(task)
    assert task.context["llm_provider"] == "openai"
    assert task.context["llm_auth_mode"] == "api_key"
    assert task.context["llm_model"] == "gpt-5.4"
    assert task.context["llm_execution_mode"] == "default"
    assert task.provider == "openai"
    assert task.account_id == account_id
    assert task.model == "gpt-5.4"
    assert task.estimated_cost_usd is not None

    provider_tasks = (
        (await db_session.execute(select(Task).where(Task.provider == "openai")))
        .scalars()
        .all()
    )
    assert any(t.id == task.id for t in provider_tasks)


@pytest.mark.asyncio
async def test_exact_route_rejects_mismatched_runtime_identity(
    client: AsyncClient, db_session
):
    from app.max_plan_pool import EXACT_MODEL_ROUTE_CONTEXT_KEY
    from sqlalchemy.orm.attributes import flag_modified

    project = Project(name="Exact Runtime Telemetry", user_id="test-user-exact-runtime")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)
    exact_model = "gpt-5.6-sol"
    task = Task(
        project_id=project.id,
        payloads=[
            {
                "type": "create",
                "model": exact_model,
                "effort": "high",
                "provider_preference": ["openai"],
            }
        ],
        vm_instance_id="agent-vm-exact-runtime",
        status=TaskStatus.IN_PROGRESS,
        context={
            EXACT_MODEL_ROUTE_CONTEXT_KEY: {
                "provider": "openai",
                "model": exact_model,
                "effort": "high",
            },
            "llm_provider": "openai",
            "llm_auth_mode": "oauth",
            "llm_model": exact_model,
        },
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)
    token = create_agent_token(str(task.id), "agent-vm-exact-runtime")

    reported_mismatch = await client.post(
        "/api/agent/status",
        headers={"x-agent-token": token},
        json={
            "task_id": str(task.id),
            "status": "IN_PROGRESS",
            "provider": "openai",
            "model": "gpt-5.5",
        },
    )
    assert reported_mismatch.status_code == 409
    assert "exact_route_runtime_mismatch" in reported_mismatch.text
    await db_session.refresh(task)
    assert task.status == TaskStatus.IN_PROGRESS
    assert task.context["llm_model"] == exact_model

    stale_context = dict(task.context or {})
    stale_context["llm_model"] = "gpt-5.5"
    task.context = stale_context
    flag_modified(task, "context")
    db_session.add(task)
    await db_session.commit()
    assigned_mismatch = await client.post(
        "/api/agent/status",
        headers={"x-agent-token": token},
        json={
            "task_id": str(task.id),
            "status": "IN_PROGRESS",
        },
    )
    assert assigned_mismatch.status_code == 409
    assert "exact_route_runtime_mismatch" in assigned_mismatch.text
    await db_session.refresh(task)
    assert task.status == TaskStatus.IN_PROGRESS
    assert task.context["llm_model"] == "gpt-5.5"
    assert task.context[EXACT_MODEL_ROUTE_CONTEXT_KEY]["model"] == exact_model


@pytest.mark.asyncio
async def test_terminal_heartbeat_records_atomic_provider_model_pair(
    client: AsyncClient, db_session, mocker
):
    """Terminal heartbeat must record (provider, model) as an atomic pair.

    Three sub-cases in one test to satisfy the acceptance gate:
    1. Agent-reported pair wins over context pair when both present.
    2. Context pair used atomically when agent reports neither field.
    3. Mixed sources (context provider only + agent model only) are ignored
       rather than producing a chimera row.
    """
    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    now = _utcnow()

    project = Project(name="Atomic Pair Test", user_id="test-user-atomic")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    # --- sub-case 1: agent-reported pair wins over context pair ---
    task1 = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        vm_instance_id="agent-vm-atomic-1",
        status=TaskStatus.IN_PROGRESS,
        vm_provisioned_at=now - timedelta(minutes=5),
        context={
            "llm_provider": "anthropic",
            "llm_model": "claude-fable-5",
        },
    )
    db_session.add(task1)
    await db_session.commit()
    await db_session.refresh(task1)

    token1 = create_agent_token(str(task1.id), "agent-vm-atomic-1")
    resp1 = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task1.id),
            "status": "COMPLETED",
            "artifact_type": "ERROR_LOG",
            "logs": "ran on fallback model",
            "provider": "anthropic",
            "model": "claude-opus-4-8",
        },
        headers={"x-agent-token": token1},
    )
    assert resp1.status_code == 200
    await db_session.refresh(task1)
    # Agent reported a different model (fallback) — agent pair should win
    assert task1.provider == "anthropic"
    assert task1.model == "claude-opus-4-8", (
        "agent-reported model must win over context model when both provider+model present"
    )

    # --- sub-case 2: context pair used atomically when agent reports neither ---
    task2 = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        vm_instance_id="agent-vm-atomic-2",
        status=TaskStatus.IN_PROGRESS,
        vm_provisioned_at=now - timedelta(minutes=5),
        context={
            "llm_account_id": "acct-2",
            "max_plan_account_id": "acct-2",
            "llm_provider": "anthropic",
            "llm_model": "claude-opus-4-8",
        },
    )
    db_session.add(task2)
    await db_session.commit()
    await db_session.refresh(task2)

    token2 = create_agent_token(str(task2.id), "agent-vm-atomic-2")
    resp2 = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task2.id),
            "status": "COMPLETED",
            "artifact_type": "ERROR_LOG",
            "logs": "no provider/model in payload",
            # No provider or model in payload
        },
        headers={"x-agent-token": token2},
    )
    assert resp2.status_code == 200
    await db_session.refresh(task2)
    # Context pair should be used atomically
    assert task2.provider == "anthropic"
    assert task2.model == "claude-opus-4-8", (
        "context pair must be recorded atomically when agent reports no provider+model"
    )

    # --- sub-case 3: no chimera — context has only provider (no model), agent has only model ---
    task3 = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        vm_instance_id="agent-vm-atomic-3",
        status=TaskStatus.IN_PROGRESS,
        vm_provisioned_at=now - timedelta(minutes=5),
        context={
            "llm_account_id": "acct-3",
            "max_plan_account_id": "acct-3",
            "llm_provider": "openai",
            # no llm_model in context
        },
    )
    db_session.add(task3)
    await db_session.commit()
    await db_session.refresh(task3)

    token3 = create_agent_token(str(task3.id), "agent-vm-atomic-3")
    resp3 = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task3.id),
            "status": "COMPLETED",
            "artifact_type": "ERROR_LOG",
            "logs": "partial sources",
            "model": "claude-sonnet-4-6",
            # No provider in payload — only model
        },
        headers={"x-agent-token": token3},
    )
    assert resp3.status_code == 200
    await db_session.refresh(task3)
    assert task3.provider is None
    assert task3.model is None
    assert task3.context.get("llm_provider") == "openai"
    assert "llm_model" not in task3.context


@pytest.mark.asyncio
async def test_agent_status_cache_miss_uses_db_account_identity(
    client: AsyncClient, db_session, mocker
):
    """A cold API instance must not accept account A + provider/model B."""
    import app.max_plan_pool as pool_mod
    from app.shared_state import runtime_config as _runtime_config

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch.object(pool_mod, "_account_by_id", {})
    mocker.patch.dict(
        _runtime_config,
        {
            "provider_tier_model_map": {
                "openai": {
                    "opus": "gpt-5.6-sol",
                    "sonnet": "gpt-5.6-terra",
                    "haiku": "gpt-5.4-mini",
                },
                "anthropic": {
                    "opus": "claude-opus-4-8",
                    "sonnet": "claude-sonnet-4-6",
                    "haiku": "claude-haiku-4-5-20251001",
                },
            }
        },
        clear=False,
    )

    project = Project(name="Cold identity cache", user_id="cold-identity-user")
    account = MaxPlanAccount(
        user_id="cold-identity-user",
        name="cold-openai",
        provider=LLMProviderName.OPENAI,
        auth_mode=LLMAuthMode.OAUTH,
    )
    db_session.add(project)
    db_session.add(account)
    await db_session.commit()
    await db_session.refresh(project)
    await db_session.refresh(account)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "quality_tier": "sonnet"}],
        vm_instance_id="agent-vm-cold-identity",
        status=TaskStatus.IN_PROGRESS,
        vm_provisioned_at=_utcnow() - timedelta(minutes=5),
        llm_account_id=str(account.id),
        context={
            "llm_account_id": str(account.id),
            "max_plan_account_id": str(account.id),
            "llm_provider": "anthropic",
            "llm_auth_mode": "oauth",
            "llm_model": "claude-sonnet-4-6",
        },
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-cold-identity")
    response = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task.id),
            "status": "COMPLETED",
            "artifact_type": "ERROR_LOG",
            "logs": "attempted cross-provider report",
            "provider": "anthropic",
            "model": "claude-sonnet-4-6",
        },
        headers={"x-agent-token": token},
    )

    assert response.status_code == 200
    await db_session.refresh(task)
    assert task.llm_account_id == str(account.id)
    assert task.context.get("llm_provider") == "openai"
    assert task.context.get("llm_auth_mode") == "oauth"
    assert task.context.get("llm_model") == "gpt-5.6-terra"
    assert task.provider == "openai"
    assert task.model == "gpt-5.6-terra"


