@pytest.mark.asyncio
async def test_completed_teardown_defer_is_provider_aware_noop_single_provider(
    client: AsyncClient, db_session, mocker, monkeypatch
):
    """Single-provider projects still warm-reuse: a COMPLETED VM defers teardown
    when the project has eligible backlog work whose provider is compatible with
    the VM's boot manifest.

    Regression guard for the provider-aware teardown-defer in
    update_agent_status: the eligibility check is now passed the completing
    task's frozen boot identity (provider/account/model), but a fungible
    (provider=None) backlog task — the dominant single-provider case — must NOT
    be filtered out, so the VM is held for warm reuse exactly as before.
    """
    import app.shared_state as _ss

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mock_teardown = mocker.patch("app.vm_lifecycle.schedule_deferred_backlog_teardown")
    mock_delete = mocker.patch("app.vm_lifecycle.fire_and_forget_vm_delete")
    monkeypatch.setitem(_ss.runtime_config, "warm_backlog_reuse_enabled", True)

    project = Project(name="Provider-Aware Defer Noop", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    # Fungible (provider=None) backlog work — the dominant single-provider case.
    backlog = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        status=TaskStatus.QUEUED,
    )
    completing = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        vm_instance_id="agent-vm-defer-noop",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add_all([backlog, completing])
    await db_session.commit()
    await db_session.refresh(completing)

    token = create_agent_token(str(completing.id), "agent-vm-defer-noop")
    payload = {
        "task_id": str(completing.id),
        "status": "COMPLETED",
        "logs": "done",
        "provider": "anthropic",
    }
    resp = await client.post(
        "/api/agent/status", json=payload, headers={"x-agent-token": token}
    )
    assert resp.status_code == 200

    # VM held for warm reuse, NOT torn down on completion.
    mock_teardown.assert_called_once_with("agent-vm-defer-noop")
    mock_delete.assert_not_called()


@pytest.mark.asyncio
async def test_completed_teardown_proceeds_when_backlog_provider_mismatch(
    client: AsyncClient, db_session, mocker, monkeypatch
):
    """A COMPLETED VM whose only backlog work is pinned to a DIFFERENT provider
    must NOT defer teardown — that work would run on the wrong frozen account, so
    it should cold-dispatch and the idle VM should be torn down as before."""
    import app.shared_state as _ss

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mock_teardown = mocker.patch("app.vm_lifecycle.schedule_deferred_backlog_teardown")
    mock_delete = mocker.patch("app.vm_lifecycle.fire_and_forget_vm_delete")
    monkeypatch.setitem(_ss.runtime_config, "warm_backlog_reuse_enabled", True)

    project = Project(name="Provider-Aware Defer Mismatch", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    # Backlog work pinned/recorded to a provider the boot VM cannot run.
    backlog = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        status=TaskStatus.QUEUED,
        provider="openai",
    )
    completing = Task(
        project_id=project.id,
        payloads=[{"type": "create"}],
        vm_instance_id="agent-vm-defer-mismatch",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add_all([backlog, completing])
    await db_session.commit()
    await db_session.refresh(completing)

    token = create_agent_token(str(completing.id), "agent-vm-defer-mismatch")
    payload = {
        "task_id": str(completing.id),
        "status": "COMPLETED",
        "logs": "done",
        "provider": "anthropic",
    }
    resp = await client.post(
        "/api/agent/status", json=payload, headers={"x-agent-token": token}
    )
    assert resp.status_code == 200

    # Incompatible backlog → no defer; VM torn down on completion.
    mock_teardown.assert_not_called()
    mock_delete.assert_called_once_with(
        "agent-vm-defer-mismatch", reason="agent_completion"
    )


@pytest.mark.asyncio
async def test_agent_claim_retry_is_idempotent(client: AsyncClient, db_session):
    """
    A second claim from the same VM shortly after a successful first claim must
    replay the same task payload instead of 404'ing. The agent's apiPost retries
    on network errors / 30s timeout aborts, and if the first POST's 200 response
    was lost after the server committed PROVISIONING -> IN_PROGRESS, the retry
    would otherwise kill the task with PRE_CLAIM_FAILED.
    """
    project = Project(name="Concurrent Claim Test", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "run"}],
        vm_instance_id="agent-vm-concurrent",
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-concurrent")
    headers = {"x-agent-token": token}

    resp1 = await client.post("/api/agent/claim", headers=headers)
    assert resp1.status_code == 200

    resp2 = await client.post("/api/agent/claim", headers=headers)
    assert resp2.status_code == 200
    assert resp2.json()["task_id"] == resp1.json()["task_id"]


@pytest.mark.asyncio
async def test_research_contract_marker_is_not_backfilled_on_legacy_claim_replay(
    client: AsyncClient,
    db_session,
):
    """An already-running pre-release task keeps the legacy output contract."""

    project = Project(name="Legacy Research Claim Replay", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "research", "prompt": "Inspect the existing system"}],
        vm_instance_id="agent-vm-legacy-research-replay",
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), task.vm_instance_id)
    headers = {
        "x-agent-token": token,
        "x-research-output-contract-version": "2",
    }
    first = await client.post("/api/agent/claim", headers=headers)
    assert first.status_code == 200
    assert first.json()["context"]["research_output_contract_version"] == 2

    # Model a task whose original claim happened before the marker release while
    # retaining the real immutable replay receipt/token binding.
    await db_session.refresh(task)
    legacy_context = dict(task.context or {})
    legacy_context.pop("research_output_contract_version", None)
    task.context = legacy_context
    db_session.add(task)
    await db_session.commit()

    replay = await client.post("/api/agent/claim", headers=headers)
    assert replay.status_code == 200
    assert "research_output_contract_version" not in replay.json()["context"]
    await db_session.refresh(task)
    assert "research_output_contract_version" not in (task.context or {})

    stale_runner_task = Task(
        project_id=project.id,
        payloads=[{"type": "research", "prompt": "Claim from a stale runner"}],
        vm_instance_id="agent-vm-stale-research-runner",
        context={"research_output_contract_version": 2},
    )
    db_session.add(stale_runner_task)
    await db_session.commit()
    await db_session.refresh(stale_runner_task)
    stale_token = create_agent_token(
        str(stale_runner_task.id), stale_runner_task.vm_instance_id
    )
    stale_claim = await client.post(
        "/api/agent/claim", headers={"x-agent-token": stale_token}
    )
    assert stale_claim.status_code == 200
    assert "research_output_contract_version" not in stale_claim.json()["context"]
    await db_session.refresh(stale_runner_task)
    assert "research_output_contract_version" not in (
        stale_runner_task.context or {}
    )


@pytest.mark.asyncio
async def test_resident_claim_survives_aborted_retry_projection_session(
    client: AsyncClient,
    db_session,
    monkeypatch,
):
    project = Project(name="Resident claim projection failure", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    session_id = f"ss-{uuid.uuid4()}"
    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "run"}],
        vm_instance_id="agent-vm-resident-projection-failure",
        status=TaskStatus.PROVISIONING,
        context={
            "_resident_session": True,
            "strategic_session_id": session_id,
            "_resident_worker_generation": 1,
        },
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    async def abort_projection_transaction(projection_session, **_kwargs):
        # This is a real PostgreSQL transaction abort, not merely a mocked
        # exception. If claim used its main session here, later response-building
        # reads would raise PendingRollbackError and turn a durable claim into 500.
        await projection_session.execute(
            text("SELECT * FROM deliberately_missing_retry_projection_table")
        )

    monkeypatch.setattr(
        "app.strategic_resident_session.clear_resident_worker_retry_wait",
        abort_projection_transaction,
    )
    token = create_agent_token(
        str(task.id), "agent-vm-resident-projection-failure"
    )
    response = await client.post(
        "/api/agent/claim",
        headers={"x-agent-token": token},
    )

    assert response.status_code == 200
    assert response.json()["task_id"] == str(task.id)
    await db_session.refresh(task)
    assert task.status == TaskStatus.IN_PROGRESS


@pytest.mark.asyncio
async def test_agent_claim_idempotent_replay_expires(client: AsyncClient, db_session):
    """
    Idempotent replay only fires within 5 min of the original claim. Beyond
    that window a stray claim from the same VM is a real anomaly even when the
    legitimate worker has heartbeated recently. Mutable heartbeat liveness must
    never extend the immutable replay window.
    """
    project = Project(name="Claim Replay Expiry", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "run"}],
        vm_instance_id="agent-vm-stale-replay",
        status=TaskStatus.PROVISIONING,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-stale-replay")
    headers = {"x-agent-token": token}
    first = await client.post("/api/agent/claim", headers=headers)
    assert first.status_code == 200

    await db_session.refresh(task)
    context = dict(task.context or {})
    replay_record = dict(context["_agent_claim_replay"])
    replay_record["claimed_at"] = (_utcnow() - timedelta(minutes=10)).isoformat()
    context["_agent_claim_replay"] = replay_record
    task.context = context
    task.last_heartbeat = _utcnow()
    db_session.add(task)
    await db_session.commit()

    replay = await client.post("/api/agent/claim", headers=headers)
    assert replay.status_code == 409


