@pytest.mark.asyncio
async def test_agent_heartbeat_upserts_vm_contact(client: AsyncClient, db_session):
    """Heartbeat false-reap fix (option B): a heartbeat upserts an uncontended
    vmcontact row keyed on vm_instance_id, independent of the contended task-row
    write. A second heartbeat advances last_contact_at in place (one row/VM)."""
    from app.models import VmContact

    project = Project(name="VM Contact Test", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    vm_id = "agent-vm-contact"
    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "run"}],
        vm_instance_id=vm_id,
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    # No vm_contact row before the first heartbeat.
    assert await db_session.get(VmContact, vm_id) is None

    token = create_agent_token(str(task.id), vm_id)
    headers = {"x-agent-token": token}
    payload = {"task_id": str(task.id), "status_message": "still running"}

    resp = await client.post("/api/agent/heartbeat", json=payload, headers=headers)
    assert resp.status_code == 200

    # vm_contact row exists with a fresh last_contact_at.
    contact = await db_session.get(VmContact, vm_id)
    assert contact is not None
    first_contact_at = contact.last_contact_at
    assert first_contact_at is not None
    assert first_contact_at > _utcnow() - timedelta(minutes=5)

    # Second heartbeat upserts in place (still exactly one row for this VM) and
    # advances last_contact_at.
    db_session.expire(contact)
    resp2 = await client.post("/api/agent/heartbeat", json=payload, headers=headers)
    assert resp2.status_code == 200
    contact2 = await db_session.get(VmContact, vm_id)
    assert contact2 is not None
    assert contact2.last_contact_at >= first_contact_at
    # A tool-less heartbeat leaves last_tool_use_at untouched (NULL so far).
    assert contact2.last_tool_use_at is None


@pytest.mark.asyncio
async def test_agent_heartbeat_upserts_vm_contact_tool_use(
    client: AsyncClient, db_session
):
    """Fix 3b: a heartbeat carrying tool_trace also upserts the off-row
    vmcontact.last_tool_use_at so the reaper's progress-stall branch can spare a
    lock-starved-but-progressing agent. The stored value advances monotonically:
    a stale or absent tool_trace tail never regresses a fresher recorded value."""
    from app.models import VmContact

    project = Project(name="VM Contact Tool Use", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    vm_id = "agent-vm-tooluse"
    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "run"}],
        vm_instance_id=vm_id,
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), vm_id)
    headers = {"x-agent-token": token}

    # Heartbeat WITH a tool_trace whose tail is a recent ISO-8601 timestamp.
    recent = (_utcnow() - timedelta(seconds=20)).isoformat()
    payload = {
        "task_id": str(task.id),
        "status_message": "calling tools",
        "tool_trace": [
            {"t": recent, "tool": "Bash", "input_preview": "ls"},
        ],
    }
    resp = await client.post("/api/agent/heartbeat", json=payload, headers=headers)
    assert resp.status_code == 200

    contact = await db_session.get(VmContact, vm_id)
    assert contact is not None
    assert contact.last_tool_use_at is not None
    recorded = contact.last_tool_use_at
    # Within a few seconds of the supplied tail timestamp (tz stripped to naive).
    assert recorded > _utcnow() - timedelta(minutes=2)

    # Monotonic: a LATER heartbeat whose tool_trace tail is OLDER than what we
    # already recorded must NOT regress the stored value.
    db_session.expire(contact)
    older = (_utcnow() - timedelta(minutes=10)).isoformat()
    payload_old = {
        "task_id": str(task.id),
        "tool_trace": [{"t": older, "tool": "Read", "input_preview": "x"}],
    }
    resp2 = await client.post("/api/agent/heartbeat", json=payload_old, headers=headers)
    assert resp2.status_code == 200
    contact2 = await db_session.get(VmContact, vm_id)
    assert contact2.last_tool_use_at >= recorded

    # Monotonic: a tool-LESS heartbeat must not blank the stored progress stamp.
    db_session.expire(contact2)
    resp3 = await client.post(
        "/api/agent/heartbeat",
        json={"task_id": str(task.id), "status_message": "thinking"},
        headers=headers,
    )
    assert resp3.status_code == 200
    contact3 = await db_session.get(VmContact, vm_id)
    assert contact3.last_tool_use_at is not None
    assert contact3.last_tool_use_at >= recorded


@pytest.mark.asyncio
async def test_agent_heartbeat_records_active_tool_subprogress_after_status_override(
    client: AsyncClient, db_session, mocker
):
    """An in-flight long command renews its lease when provider output is quiet.

    Regression: task 45364a8f kept heartbeating during ``./check test``, but the
    Codex JSONL stream buffered command output for longer than the medium-scope
    progress budget. The explicit active-tool field remains present while the
    command is in flight, so heartbeat receipt must renew both task-scoped and
    shared progress clocks independently of the stale output timestamp.
    """
    from app.models import TaskContact, VmContact
    from sqlalchemy.ext.asyncio import async_sessionmaker

    # _record_vm_contact intentionally commits through an independent session
    # so task-row lock contention cannot drop the liveness signal. Bind that
    # session to this test database as well as the request-scoped fixture.
    contact_session = async_sessionmaker(db_session.bind, expire_on_commit=False)
    mocker.patch("app.routers.agent.AsyncSessionLocal", contact_session)

    project = Project(name="Active Tool Progress", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    vm_id = "runner:active-tool-progress"
    task = Task(
        project_id=project.id,
        status=TaskStatus.IN_PROGRESS,
        vm_instance_id=vm_id,
        started_at=_utcnow() - timedelta(minutes=10),
        last_heartbeat=_utcnow(),
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    headers = {"x-agent-token": create_agent_token(str(task.id), vm_id)}
    invocation_at = _utcnow() - timedelta(minutes=15)
    subprogress_at = _utcnow() - timedelta(minutes=14)
    heartbeat_started_at = _utcnow()
    resp = await client.post(
        "/api/agent/heartbeat",
        json={
            "task_id": str(task.id),
            "status_message": (
                "The publication gate remains clean "
                "(8m 0s elapsed, last sub-progress 20s ago)"
            ),
            "tool_trace": [
                {
                    "t": invocation_at.isoformat(),
                    "tool": "Bash",
                    "input_preview": "./check test",
                }
            ],
            "active_tool_progress_at": subprogress_at.isoformat(),
        },
        headers=headers,
    )
    assert resp.status_code == 200

    await db_session.refresh(task)
    shared = await db_session.get(VmContact, vm_id)
    scoped = await db_session.get(TaskContact, task.id)
    assert task.last_tool_use_at is not None
    assert task.last_tool_use_at >= heartbeat_started_at
    assert shared is not None
    assert shared.last_tool_use_at is not None
    assert shared.last_tool_use_at >= heartbeat_started_at
    assert scoped is not None
    assert scoped.last_tool_use_at is not None
    assert scoped.last_tool_use_at >= heartbeat_started_at


