@pytest.mark.smoketest
@pytest.mark.asyncio
async def test_playbook_set_and_get(client: AsyncClient, db_session):
    """Tests setting and retrieving playbook entries via POST /api/agent/playbook."""
    project = Project(name="Playbook Test", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "Do something"}],
        vm_instance_id="agent-vm-playbook1",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-playbook1")
    headers = {"x-agent-token": token}

    # Set two playbook entries
    resp = await client.post(
        "/api/agent/playbook",
        json={
            "task_id": str(task.id),
            "op": "set",
            "key": "build-commands",
            "value": "npm run build",
        },
        headers=headers,
    )
    assert resp.status_code == 200
    data = resp.json()
    assert data["status"] == "ok"
    assert data["op"] == "set"
    assert data["key"] == "build-commands"
    assert data["revision"] == 1

    resp2 = await client.post(
        "/api/agent/playbook",
        json={
            "task_id": str(task.id),
            "op": "set",
            "key": "lint-rules",
            "value": "eslint --max-warnings 0",
        },
        headers=headers,
    )
    assert resp2.status_code == 200
    assert resp2.json()["revision"] == 2

    # Verify stored in design_doc
    await db_session.refresh(project)
    assert project.design_doc is not None
    assert "playbook/build-commands" in project.design_doc
    assert project.design_doc["playbook/build-commands"]["content"] == "npm run build"
    assert project.design_doc["playbook/build-commands"]["source_task_id"] == str(
        task.id
    )
    assert "playbook/lint-rules" in project.design_doc

    # Get all playbook entries
    resp3 = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "get"},
        headers=headers,
    )
    assert resp3.status_code == 200
    data3 = resp3.json()
    assert data3["status"] == "ok"
    assert data3["op"] == "get"
    entries = data3["entries"]
    assert "build-commands" in entries
    assert entries["build-commands"]["content"] == "npm run build"
    assert "lint-rules" in entries

    # Get single playbook entry by key
    resp_key = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "get", "key": "build-commands"},
        headers=headers,
    )
    assert resp_key.status_code == 200
    data_key = resp_key.json()
    assert data_key["status"] == "ok"
    assert data_key["op"] == "get"
    key_entries = data_key["entries"]
    assert "build-commands" in key_entries
    assert key_entries["build-commands"]["content"] == "npm run build"
    assert "lint-rules" not in key_entries

    # Get non-existent key returns empty entries
    resp_miss = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "get", "key": "nonexistent-key"},
        headers=headers,
    )
    assert resp_miss.status_code == 200
    assert resp_miss.json()["entries"] == {}

    # List keys
    resp4 = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "list"},
        headers=headers,
    )
    assert resp4.status_code == 200
    data4 = resp4.json()
    assert set(data4["keys"]) == {"build-commands", "lint-rules"}

    await db_session.refresh(project)
    assert "playbook/lint-rules" in project.design_doc
    assert "playbook/build-commands" in project.design_doc


@pytest.mark.smoketest
@pytest.mark.asyncio
async def test_playbook_get_with_key(client: AsyncClient, db_session):
    """Key-scoped get returns a single entry; no-key returns all; unknown key returns empty."""
    project = Project(name="Playbook Key Test", user_id="test-user-456")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "Do something"}],
        vm_instance_id="agent-vm-playbook-key",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-playbook-key")
    headers = {"x-agent-token": token}

    # Set two playbook entries
    for kv in [("key-one", "value-one"), ("key-two", "value-two")]:
        resp = await client.post(
            "/api/agent/playbook",
            json={"task_id": str(task.id), "op": "set", "key": kv[0], "value": kv[1]},
            headers=headers,
        )
        assert resp.status_code == 200

    # Get with a specific key — returns only that entry
    resp = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "get", "key": "key-one"},
        headers=headers,
    )
    assert resp.status_code == 200
    data = resp.json()
    assert data["status"] == "ok"
    assert data["op"] == "get"
    assert set(data["entries"].keys()) == {"key-one"}
    assert data["entries"]["key-one"]["content"] == "value-one"

    # Get with non-existent key — returns empty dict
    resp = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "get", "key": "nonexistent"},
        headers=headers,
    )
    assert resp.status_code == 200
    data = resp.json()
    assert data["entries"] == {}

    # Get with no key — returns all entries (backward compatible)
    resp = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "get"},
        headers=headers,
    )
    assert resp.status_code == 200
    data = resp.json()
    assert set(data["entries"].keys()) == {"key-one", "key-two"}


@pytest.mark.asyncio
async def test_playbook_set_records_branch_head_provenance(
    client: AsyncClient, db_session
):
    """A set with branch/head_sha stamps provenance; get surfaces it; absent
    provenance stays backward-compatible (empty strings, no error)."""
    project = Project(name="Provenance Test", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "Do something"}],
        vm_instance_id="agent-vm-prov",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-prov")
    headers = {"x-agent-token": token}

    # Set WITH provenance.
    resp = await client.post(
        "/api/agent/playbook",
        json={
            "task_id": str(task.id),
            "op": "set",
            "key": "with-prov",
            "value": "module X defines Y",
            "branch": "automain",
            "head_sha": "abc1234",
        },
        headers=headers,
    )
    assert resp.status_code == 200

    # Set WITHOUT provenance (legacy callers / non-git workspaces).
    resp_legacy = await client.post(
        "/api/agent/playbook",
        json={
            "task_id": str(task.id),
            "op": "set",
            "key": "no-prov",
            "value": "run tests with Z",
        },
        headers=headers,
    )
    assert resp_legacy.status_code == 200

    # Provenance is persisted on the entry.
    await db_session.refresh(project)
    stored = project.design_doc["playbook/with-prov"]
    assert stored["branch"] == "automain"
    assert stored["head_sha"] == "abc1234"
    # Legacy entry carries no provenance keys.
    legacy = project.design_doc["playbook/no-prov"]
    assert "branch" not in legacy
    assert "head_sha" not in legacy

    # get surfaces provenance; absent provenance reads back as "".
    resp_get = await client.post(
        "/api/agent/playbook",
        json={"task_id": str(task.id), "op": "get"},
        headers=headers,
    )
    assert resp_get.status_code == 200
    entries = resp_get.json()["entries"]
    assert entries["with-prov"]["branch"] == "automain"
    assert entries["with-prov"]["head_sha"] == "abc1234"
    assert entries["no-prov"]["branch"] == ""
    assert entries["no-prov"]["head_sha"] == ""


