@pytest.mark.asyncio
async def test_agent_ws_conversation_terminal_relays_without_touching_the_db(mocker):
    """A tombstone must survive the exact failures it exists to report.

    Claim released, controller retired, task moved off IN_PROGRESS: those are
    the states that most need the preview retracted, and they are precisely the
    ones the liveness fence rejects. Gating the tombstone on the healthy path
    strands a partial answer on screen that looks delivered and does not exist
    server-side.

    The relay's DB budget is pinned two ways at once. `AsyncSessionLocal` is
    handed exactly TWO sessions — the auth one and the loop's own periodic
    task recheck — so opening a third for the tombstone raises. And the recheck
    session's `execute` is poisoned, so reusing it to run the claim fence
    raises too. Either regression fails loudly instead of passing.
    """
    import json as _json
    import app.routers.projects as projects_module
    from fastapi import WebSocketDisconnect
    from unittest.mock import AsyncMock, MagicMock

    task_id = uuid.uuid4()
    project_id = uuid.uuid4()
    claim_id = uuid.uuid4()
    token = create_agent_token(str(task_id), "agent-vm-tomb", project_id=str(project_id))
    task = MagicMock(
        id=task_id,
        project_id=project_id,
        vm_instance_id="agent-vm-tomb",
        status=TaskStatus.IN_PROGRESS,
        context={"strategic_session_id": "session-tomb"},
    )
    auth_result = MagicMock()
    auth_result.scalars.return_value.first.return_value = task
    auth_session = AsyncMock()
    auth_session.execute = AsyncMock(return_value=auth_result)
    auth_cm = AsyncMock()
    auth_cm.__aenter__.return_value = auth_session
    auth_cm.__aexit__.return_value = None

    # The receive loop rechecks the task row once per inbound frame. That
    # session is expected; a query issued THROUGH it is not.
    recheck_session = AsyncMock()
    recheck_session.get = AsyncMock(return_value=task)
    recheck_session.execute = AsyncMock(
        side_effect=AssertionError("terminal relay must not query the claim fence")
    )
    recheck_session.scalar = AsyncMock(
        side_effect=AssertionError("terminal relay must not read the sequence")
    )
    recheck_cm = AsyncMock()
    recheck_cm.__aenter__.return_value = recheck_session
    recheck_cm.__aexit__.return_value = None
    mocker.patch(
        "app.routers.projects.AsyncSessionLocal",
        side_effect=[auth_cm, recheck_cm],
    )
    mocker.patch(
        "app.routers.projects.manager.check_and_add_ip",
        new_callable=AsyncMock,
        return_value=True,
    )
    mocker.patch("app.routers.projects.manager.disconnect", new_callable=AsyncMock)
    broadcast = mocker.patch(
        "app.routers.projects.broadcast_to_project", new_callable=AsyncMock
    )
    ws = AsyncMock()
    ws.receive_json = AsyncMock(return_value={"token": token})
    ws.receive_text = AsyncMock(side_effect=[
        _json.dumps({
            "type": "conversation_message_delta",
            "payload": {
                "session_id": "session-tomb",
                "task_id": str(task_id),
                "claim_id": str(claim_id),
                "idempotency_key": "typed-fast:claim:reply",
                "seq": 4,
                "content": "",
                "terminal": "failed",
            },
        }),
        WebSocketDisconnect(),
    ])

    await projects_module.agent_websocket_endpoint(ws, task_id)

    broadcast.assert_awaited_once()
    payload = broadcast.await_args.args[2]
    assert broadcast.await_args.args[:2] == (str(project_id), "message_updated")
    assert payload["message"]["context"]["_conversation_streaming_terminal"] == "failed"
    assert payload["message"]["context"]["_conversation_streaming_delta"] is False


@pytest.mark.asyncio
async def test_agent_ws_conversation_delta_rejects_unknown_terminal_state(mocker):
    """An unrecognised terminal string is a malformed frame, not a delta.

    Treating it as a delta would relay attacker-chosen text through the
    tombstone path, which deliberately skips the liveness fence.
    """
    import json as _json
    import app.routers.projects as projects_module
    from fastapi import WebSocketDisconnect
    from unittest.mock import AsyncMock, MagicMock

    task_id = uuid.uuid4()
    project_id = uuid.uuid4()
    token = create_agent_token(str(task_id), "agent-vm-bad", project_id=str(project_id))
    task = MagicMock(
        id=task_id,
        project_id=project_id,
        vm_instance_id="agent-vm-bad",
        status=TaskStatus.IN_PROGRESS,
        context={"strategic_session_id": "session-bad"},
    )
    auth_result = MagicMock()
    auth_result.scalars.return_value.first.return_value = task
    auth_session = AsyncMock()
    auth_session.execute = AsyncMock(return_value=auth_result)
    auth_cm = AsyncMock()
    auth_cm.__aenter__.return_value = auth_session
    auth_cm.__aexit__.return_value = None
    # Auth session plus the loop's one periodic task recheck. A malformed frame
    # is rejected before any relay DB work, so nothing else may open a session.
    recheck_session = AsyncMock()
    recheck_session.get = AsyncMock(return_value=task)
    recheck_session.execute = AsyncMock(
        side_effect=AssertionError("a malformed frame must not reach the relay query")
    )
    recheck_cm = AsyncMock()
    recheck_cm.__aenter__.return_value = recheck_session
    recheck_cm.__aexit__.return_value = None
    mocker.patch(
        "app.routers.projects.AsyncSessionLocal",
        side_effect=[auth_cm, recheck_cm],
    )
    mocker.patch(
        "app.routers.projects.manager.check_and_add_ip",
        new_callable=AsyncMock,
        return_value=True,
    )
    mocker.patch("app.routers.projects.manager.disconnect", new_callable=AsyncMock)
    broadcast = mocker.patch(
        "app.routers.projects.broadcast_to_project", new_callable=AsyncMock
    )
    ws = AsyncMock()
    ws.receive_json = AsyncMock(return_value={"token": token})
    ws.receive_text = AsyncMock(side_effect=[
        _json.dumps({
            "type": "conversation_message_delta",
            "payload": {
                "session_id": "session-bad",
                "task_id": str(task_id),
                "claim_id": str(uuid.uuid4()),
                "idempotency_key": "typed-fast:claim:reply",
                "seq": 0,
                "content": "attacker text",
                "terminal": "delivered",
            },
        }),
        WebSocketDisconnect(),
    ])

    await projects_module.agent_websocket_endpoint(ws, task_id)

    broadcast.assert_not_awaited()


def test_streaming_preview_attempt_partitions_the_projected_identity():
    """A retried attempt must project as a DIFFERENT preview.

    A provider crash re-runs the same receipt, so attempt 2 carries the same
    `idempotency_key` while its text is a new answer rather than a continuation.
    Sharing one preview id let the client weld the retry's tail onto the
    abandoned partial. The `idempotency_key` FIELD stays un-namespaced so the
    durable reply still replaces the preview by receipt identity.
    """
    from app.conversation_streaming import (
        build_streaming_reply_message,
        streaming_reply_message_id,
    )

    project_id = uuid.uuid4()
    key = "typed-fast:claim-1:reply-1"
    common = dict(
        project_id=project_id,
        task_id=uuid.uuid4(),
        session_id="session-1",
        claim_id=uuid.uuid4(),
        idempotency_key=key,
        content="text",
        sequence=4,
    )

    first = build_streaming_reply_message(**common, attempt=0)
    retry = build_streaming_reply_message(**common, attempt=1)

    assert first.id == streaming_reply_message_id(project_id, key)
    assert first.id == streaming_reply_message_id(project_id, key, 0)
    assert retry.id != first.id
    assert retry.id == streaming_reply_message_id(project_id, key, 1)
    # Receipt identity is untouched: the durable reply replaces either preview.
    assert first.idempotency_key == retry.idempotency_key == key


def test_streaming_preview_chunk_cap_matches_agent_constant():
    """The agent's wire cap and the relay's drop threshold are ONE contract.

    A chunk longer than the relay's cap is DROPPED silently, so drift between
    the two constants deletes text out of a live reply with nothing logged
    anywhere. The backend value is pinned as a literal on purpose — asserting it
    against the constant it guards would move with any change and certify
    itself.
    """
    import re as _re

    from app.routers.projects import _STREAMING_PREVIEW_MAX_CHUNK_CHARS

    assert _STREAMING_PREVIEW_MAX_CHUNK_CHARS == 1200

    source = None
    for root in (
        Path(os.getenv("AGENT_SRC_ROOT") or "/agent/src"),
        Path(__file__).resolve().parents[2] / "agent" / "src",
    ):
        candidate = root / "handlers" / "conversation-message-streamer.ts"
        if candidate.exists():
            source = candidate
            break
    if source is None:
        pytest.skip("agent/src is not mounted in this backend test image")

    match = _re.search(
        r"export const STREAM_DELTA_MAX_CHARS = ([0-9_]+);",
        source.read_text(encoding="utf-8"),
    )
    assert match is not None, "agent STREAM_DELTA_MAX_CHARS declaration not found"
    assert int(match.group(1).replace("_", "")) == _STREAMING_PREVIEW_MAX_CHUNK_CHARS


@pytest.mark.asyncio
async def test_agent_ws_closes_on_termination_without_messages(mocker):
    """
    Regression: WS must close ≤5s after task termination even when no messages
    are received (timer-driven path, not receive-driven).

    Simulates: agent opens WS, task is injected into the deny-list by the timer
    callback — no further messages are sent — the concurrent timer must fire and
    close the connection.
    """
    import asyncio
    import time as time_module
    import app.routers.agent as agent_module
    from app.routers.projects import agent_websocket_endpoint
    from unittest.mock import AsyncMock, MagicMock

    task_id = uuid.uuid4()
    project_id = uuid.uuid4()
    vm_id = "agent-vm-silent-deny"

    token = create_agent_token(
        str(task_id),
        vm_id,
        project_id=str(project_id),
    )

    mock_task = MagicMock()
    mock_task.id = task_id
    mock_task.project_id = project_id
    mock_task.vm_instance_id = vm_id
    mock_task.status = TaskStatus.IN_PROGRESS

    mock_execute_result = MagicMock()
    mock_execute_result.scalars.return_value.first.return_value = mock_task

    mock_session = AsyncMock()
    mock_session.execute = AsyncMock(return_value=mock_execute_result)

    mock_session_cm = AsyncMock()
    mock_session_cm.__aenter__.return_value = mock_session
    mock_session_cm.__aexit__.return_value = None

    mocker.patch("app.routers.projects.AsyncSessionLocal", return_value=mock_session_cm)
    mocker.patch(
        "app.routers.projects.manager.check_and_add_ip",
        new_callable=AsyncMock,
        return_value=True,
    )
    mocker.patch("app.routers.projects.manager.remove_ip")
    mocker.patch("app.routers.projects.broadcast_to_project", new_callable=AsyncMock)

    ws = AsyncMock()
    ws.receive_json = AsyncMock(return_value={"token": token})

    # receive_text blocks forever — no messages are sent after auth
    block_event = asyncio.Event()

    async def _never_return():
        await block_event.wait()
        return ""

    ws.receive_text = AsyncMock(side_effect=_never_return)
    ws.close = AsyncMock()

    # Patch asyncio.sleep so the 5s timer fires immediately and injects termination.
    async def _instant_sleep_with_inject(seconds):
        agent_module._terminated_task_ids[str(task_id)] = time_module.time()

    mocker.patch("asyncio.sleep", new=_instant_sleep_with_inject)

    await agent_websocket_endpoint(ws, task_id)

    # Connection must be closed with 1008 (Task is no longer active)
    ws.close.assert_called_once_with(code=1008, reason="Task is no longer active")

    # Unblock any lingering receive coroutines and clean up
    block_event.set()
    agent_module._terminated_task_ids.pop(str(task_id), None)


@pytest.mark.asyncio
@pytest.mark.parametrize(
    "terminal_status",
    [TaskStatus.COMPLETED, TaskStatus.BLOCKED],
    ids=["completed", "blocked"],
)
async def test_agent_ws_closes_on_db_fallback_when_denylist_misses(
    mocker, terminal_status: TaskStatus
):
    """
    Regression: WS must close ≤5s after task termination even when the
    in-memory deny-list is empty (cache miss after restart, listener gap, or
    desync). The timer-driven DB fallback must observe the terminal status in
    the DB and close the connection on the next tick.
    """
    import asyncio
    import app.routers.agent as agent_module
    from app.routers.projects import agent_websocket_endpoint
    from unittest.mock import AsyncMock, MagicMock

    task_id = uuid.uuid4()
    project_id = uuid.uuid4()
    vm_id = "agent-vm-db-fallback"

    # Ensure deny-list does NOT contain the task — this is the cache-miss case
    agent_module._terminated_task_ids.pop(str(task_id), None)

    token = create_agent_token(
        str(task_id),
        vm_id,
        project_id=str(project_id),
    )

    # Initial auth-time task: IN_PROGRESS so the handshake succeeds
    initial_task = MagicMock()
    initial_task.id = task_id
    initial_task.project_id = project_id
    initial_task.vm_instance_id = vm_id
    initial_task.status = TaskStatus.IN_PROGRESS

    # DB-fallback task: now terminal (COMPLETED) — must trigger a close
    terminal_task = MagicMock()
    terminal_task.id = task_id
    terminal_task.project_id = project_id
    terminal_task.vm_instance_id = vm_id
    terminal_task.status = terminal_status

    auth_execute_result = MagicMock()
    auth_execute_result.scalars.return_value.first.return_value = initial_task

    mock_session = AsyncMock()
    mock_session.execute = AsyncMock(return_value=auth_execute_result)
    # Subsequent session.get(Task, ...) inside the timer-driven DB fallback
    # returns the terminal task.
    mock_session.get = AsyncMock(return_value=terminal_task)

    mock_session_cm = AsyncMock()
    mock_session_cm.__aenter__.return_value = mock_session
    mock_session_cm.__aexit__.return_value = None

    mocker.patch("app.routers.projects.AsyncSessionLocal", return_value=mock_session_cm)
    mocker.patch(
        "app.routers.projects.manager.check_and_add_ip",
        new_callable=AsyncMock,
        return_value=True,
    )
    mocker.patch("app.routers.projects.manager.remove_ip")
    mocker.patch("app.routers.projects.broadcast_to_project", new_callable=AsyncMock)

    ws = AsyncMock()
    ws.receive_json = AsyncMock(return_value={"token": token})

    block_event = asyncio.Event()

    async def _never_return():
        await block_event.wait()
        return ""

    ws.receive_text = AsyncMock(side_effect=_never_return)
    ws.close = AsyncMock()

    # Patch asyncio.sleep so the 5s timer fires immediately. Deny-list stays
    # empty — only the DB fallback can detect the termination.
    async def _instant_sleep(seconds):
        return None

    mocker.patch("asyncio.sleep", new=_instant_sleep)

    await agent_websocket_endpoint(ws, task_id)

    # Confirm deny-list was NOT the trigger
    assert str(task_id) not in agent_module._terminated_task_ids
    # DB fallback must have been consulted at least once on the timer path
    assert mock_session.get.await_count >= 1
    # Connection must be closed with 1008 (Task is no longer active)
    ws.close.assert_called_once_with(code=1008, reason="Task is no longer active")

    block_event.set()


@pytest.mark.asyncio
async def test_external_api_requeue_sets_exponential_backoff(
    client: AsyncClient, db_session, mocker
):
    """
    Tests that EXTERNAL_API failures requeue with exponential backoff in retry_after.
    - 1st retry: ~2 min delay (2^1 * 120 = 240s)
    - 2nd retry: ~8 min delay (2^2 * 120 = 480s)
    - 3rd retry: ~16 min delay (2^3 * 120 = 960s)
    - After 5 retries, task is not requeued (budget exhausted)
    """
    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=mocker.AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)

    project = Project(name="Backoff Test", user_id="test-user-backoff")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    for retry_num in range(1, 4):
        task = Task(
            project_id=project.id,
            payloads=[{"cmd": "test"}],
            vm_instance_id=f"agent-vm-backoff-{retry_num}",
            status=TaskStatus.IN_PROGRESS,
            # Pre-seed provision_failures to verify it gets cleared on graceful requeue —
            # otherwise a single provision hiccup on a previously-successful task would
            # immediately exhaust the retry budget on the next dispatch.
            context={"_api_failure_retries": retry_num - 1, "provision_failures": 2},
        )
        db_session.add(task)
        await db_session.commit()
        await db_session.refresh(task)

        token = create_agent_token(str(task.id), f"agent-vm-backoff-{retry_num}")
        headers = {"x-agent-token": token}
        payload = {
            "task_id": str(task.id),
            "status": "FAILED",
            "failure_class": "EXTERNAL_API",
            "logs": "api.github.com returned 503",
        }
        before = _utcnow()
        resp = await client.post("/api/agent/status", json=payload, headers=headers)
        assert resp.status_code == 200

        await db_session.refresh(task)
        assert task.status == TaskStatus.QUEUED, f"retry {retry_num}: expected QUEUED"
        ctx = task.context or {}
        assert task.retry_after_until is not None, (
            f"retry {retry_num}: retry_after_until not set"
        )
        assert "provision_failures" not in ctx, (
            f"retry {retry_num}: provision_failures should be cleared on graceful requeue"
        )
        assert ctx.get("_api_failure_retries") == retry_num
        assert ctx.get("_fresh_attempt_started_at")

        retry_after_dt = task.retry_after_until
        expected_delay = min(2**retry_num * 120, 1800)
        actual_delay = (retry_after_dt - before).total_seconds()
        assert actual_delay >= expected_delay - 2, (
            f"retry {retry_num}: delay {actual_delay} < expected {expected_delay}"
        )
        assert actual_delay <= expected_delay + 5, (
            f"retry {retry_num}: delay {actual_delay} too large"
        )

    # 6th attempt: api_retries=5, increments to 6 > 5 → EXTERNAL_API requeue path is skipped
    # Falls through to general retry (task.attempt_count < max_retries), so no retry_after is set
    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "test"}],
        vm_instance_id="agent-vm-backoff-6",
        status=TaskStatus.IN_PROGRESS,
        context={"_api_failure_retries": 5},
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-backoff-6")
    headers = {"x-agent-token": token}
    payload = {
        "task_id": str(task.id),
        "status": "FAILED",
        "failure_class": "EXTERNAL_API",
        "logs": "api.github.com returned 503",
    }
    resp = await client.post("/api/agent/status", json=payload, headers=headers)
    assert resp.status_code == 200

    await db_session.refresh(task)
    # Falls through to general retry path — no EXTERNAL_API-specific deadline is set.
    assert task.retry_after_until is None, (
        "after EXTERNAL_API cap exceeded, retry_after_until should not be set"
    )


@pytest.mark.asyncio
async def test_reassigned_lands_cancelled_no_retry_no_alert(
    client: AsyncClient, db_session, mocker
):
    """FIX H: a REASSIGNED outcome (agent gracefully self-terminated because the
    task was superseded/reassigned/deauthed) must land CANCELLED on first
    detection — NOT retry, NOT FAILED, NOT fire a failure alert — mirroring the
    SCOPE_EMPTY->CANCELLED precedent."""
    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)
    alert_mock = mocker.patch(
        "app.alert_dispatch._maybe_create_failure_alert", new_callable=AsyncMock
    )

    project = Project(name="Reassigned Test", user_id="test-user-reassigned")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "build x"}],
        vm_instance_id="agent-vm-reassigned",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-reassigned")
    headers = {"x-agent-token": token}
    payload = {
        "task_id": str(task.id),
        "status": "FAILED",
        "failure_category": "reassigned",
        "logs": "Task reassigned/deauthorized — agent self-terminating",
    }
    resp = await client.post("/api/agent/status", json=payload, headers=headers)
    assert resp.status_code == 200

    await db_session.refresh(task)
    assert task.status == TaskStatus.CANCELLED, (
        f"REASSIGNED must land CANCELLED, not {task.status} — it is a graceful "
        f"handoff, not a code failure"
    )
    assert task.status != TaskStatus.QUEUED, "REASSIGNED must not retry"
    assert (task.context or {}).get("failure_category") == "REASSIGNED"
    alert_mock.assert_not_called()


@pytest.mark.asyncio
async def test_reassigned_with_pushed_head_records_orphaned_push_on_cancellation(
    client: AsyncClient, db_session, mocker
):
    """Kill-path regression (NeurIPS task 38b16082, 2026-08-18): a REASSIGNED
    report can land here AFTER the agent already `git push`ed a real commit but
    BEFORE PR creation ran (the heartbeat self-terminate window). With no PR
    artifact and no task_pr_linkage yet, that pushed branch/commit was
    previously orphaned — nothing on the task record pointed at it, so no
    downstream review loop could ever pick it up.

    When the agent's terminal report carries pushed_branch/pushed_head_sha
    alongside REASSIGNED, the CANCELLED task's context must record
    orphaned_push = {branch, head_sha, recorded_at} so a recovery sweep can
    find and resume the work instead of silently discarding it."""
    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)
    mocker.patch("app.alert_dispatch._maybe_create_failure_alert", new_callable=AsyncMock)

    project = Project(name="Reassigned Orphan Push Test", user_id="test-user-reassigned-push")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "build x"}],
        vm_instance_id="agent-vm-reassigned-push",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-reassigned-push")
    headers = {"x-agent-token": token}
    payload = {
        "task_id": str(task.id),
        "status": "FAILED",
        "failure_category": "reassigned",
        "logs": (
            "Task reassigned/deauthorized — heartbeat POST /api/agent/heartbeat "
            "still rejected with HTTP 403 after 3 credential re-acquisition "
            "attempts over ~60s"
        ),
        "pushed_branch": "blueprint-fix/orphan-guard-abcd123",
        "pushed_head_sha": "08823f5a1234567890abcdef1234567890abcdef",
    }
    resp = await client.post("/api/agent/status", json=payload, headers=headers)
    assert resp.status_code == 200

    await db_session.refresh(task)
    assert task.status == TaskStatus.CANCELLED
    assert (task.context or {}).get("failure_category") == "REASSIGNED"

    orphaned_push = (task.context or {}).get("orphaned_push")
    assert orphaned_push is not None, (
        "a REASSIGNED cancellation carrying a pushed head must record "
        "task.context['orphaned_push'] so downstream review can pick it up "
        "instead of orphaning the commit"
    )
    assert orphaned_push["branch"] == "blueprint-fix/orphan-guard-abcd123"
    assert orphaned_push["head_sha"] == "08823f5a1234567890abcdef1234567890abcdef"
    assert orphaned_push["recorded_at"], "recorded_at must be populated"


