@pytest.mark.asyncio
async def test_execution_timeout_retry_escalates_effort(
    client: AsyncClient, db_session, mocker
):
    """An agent-reported pure wall-clock execution timeout ("execution timed
    out") requeues with its effort tier bumped one step (medium → high), so the
    retry gets a larger budget. An OOM failure requeues with effort unchanged."""
    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)
    mocker.patch(
        "app.alert_dispatch._maybe_create_failure_alert", new_callable=AsyncMock
    )

    project = Project(name="Effort Escalation", user_id="test-user-escalate")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    async def _post_failure(vm_suffix: str, logs: str) -> Task:
        task = Task(
            project_id=project.id,
            payloads=[{"type": "create", "prompt": "build x"}],
            vm_instance_id=f"agent-vm-{vm_suffix}",
            status=TaskStatus.IN_PROGRESS,
            attempt_count=0,
            context={"effort": "medium"},
        )
        db_session.add(task)
        await db_session.commit()
        await db_session.refresh(task)

        token = create_agent_token(str(task.id), f"agent-vm-{vm_suffix}")
        payload = {"task_id": str(task.id), "status": "FAILED", "logs": logs}
        resp = await client.post(
            "/api/agent/status", json=payload, headers={"x-agent-token": token}
        )
        assert resp.status_code == 200
        await db_session.refresh(task)
        return task

    exec_task = await _post_failure("exec-timeout", "execution timed out after 3600s")
    oom_task = await _post_failure("oom", "exit code 137 out of memory")

    # Both AGENT_TIMEOUT failures requeue rather than terminal-fail.
    assert exec_task.status == TaskStatus.QUEUED
    assert oom_task.status == TaskStatus.QUEUED

    # Execution timeout escalates effort one tier; OOM leaves it unchanged.
    assert exec_task.context["effort"] == "high"
    assert exec_task.context["_effort_escalated_from"] == "medium"
    assert oom_task.context["effort"] == "medium"
    assert "_effort_escalated_from" not in oom_task.context


@pytest.mark.asyncio
async def test_blocker_lands_blocked_no_retry_no_alert(
    client: AsyncClient, db_session, mocker
):
    """A BLOCKER: outcome (./blocked) must move the task into the first-class
    BLOCKED state — NOT retry (no attempt_count burn), NOT FAILED, NOT fire a
    failure alert — and persist durable blocker metadata on the task itself.

    Regression for the precondition-blocker retry-burn: BLOCKED_PRECONDITION was
    in INFRA_CLASSES but a standalone task still ran through the FAILED->QUEUED
    retry branch, re-dispatching a VM up to max_retries against the same wall.
    """
    from app.time_utils import _utcnow

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    ensure_vm_deleted = mocker.patch(
        "app.vm_lifecycle._ensure_vm_deleted", new_callable=AsyncMock
    )
    mocker.patch(
        "app.routers.agent_status.broadcast_to_project", new_callable=AsyncMock
    )
    mocker.patch("app.alert_dispatch.broadcast_to_project", new_callable=AsyncMock)
    alert_mock = mocker.patch(
        "app.alert_dispatch._maybe_create_failure_alert", new_callable=AsyncMock
    )

    project = Project(name="Blocked Test", user_id="test-user-blocked")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "build x"}],
        vm_instance_id="agent-vm-blocked",
        last_heartbeat=_utcnow() - timedelta(minutes=5),
        started_at=_utcnow() - timedelta(minutes=7),
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-blocked")
    headers = {"x-agent-token": token}
    payload = {
        "task_id": str(task.id),
        "status": "FAILED",
        "failure_category": "BLOCKED_PRECONDITION",
        "logs": "BLOCKER: upstream rollup PR #99 not yet merged to main",
    }
    resp = await client.post("/api/agent/status", json=payload, headers=headers)
    assert resp.status_code == 200
    assert resp.json().get("status") == "blocked"

    await db_session.refresh(task)
    assert task.status == TaskStatus.BLOCKED, (
        f"BLOCKER: must land BLOCKED, not {task.status} — it is a precondition "
        f"block, not a code failure"
    )
    assert task.status != TaskStatus.QUEUED, "BLOCKED must not retry"
    # Retry budget is NOT burned.
    assert task.attempt_count == 0
    assert task.vm_instance_id is None
    assert task.last_heartbeat is None
    assert task.started_at is None
    ensure_vm_deleted.assert_awaited_once_with(
        "agent-vm-blocked", reason="blocked_precondition"
    )
    # BLOCKED_PRECONDITION classification preserved for historical consumers.
    assert (task.context or {}).get("failure_category") == "BLOCKED_PRECONDITION"
    # Durable blocker metadata persisted on the task itself, not only the status
    # message: what it waits on, a human-readable reason, and recheck timing.
    blocker = (task.context or {}).get("blocker") or {}
    assert blocker.get("source") == "agent"
    assert blocker.get("failure_class") == "BLOCKED_PRECONDITION"
    assert "BLOCKER:" in (blocker.get("reason") or "")
    assert blocker.get("recheck_at")
    assert task.blocker_kind == "upstream_dependency"
    assert "BLOCKER:" in (task.blocked_reason or "")
    assert task.blocked_at is not None
    assert task.recheck_after is not None and task.recheck_after > task.blocked_at
    # No failure alert for a non-failure outcome.
    alert_mock.assert_not_called()
    # Absent-need path: no structured need persisted when none was sent.
    assert "need" not in blocker


def test_blocked_need_schema_parses_valid_and_rejects_malformed():
    """AgentStatusPayload.blocked_need accepts a well-formed {kind, ref[, label]}
    need and rejects malformed kinds / empty refs. Backward compat: an absent
    blocked_need leaves the payload valid with the field None."""
    from pydantic import ValidationError

    from app.schemas import AgentStatusPayload

    tid = str(uuid.uuid4())
    base = {"task_id": tid, "status": "FAILED"}

    # Absent need is fine — backward compatible.
    assert AgentStatusPayload(**base).blocked_need is None

    # Valid need with each recognized kind. kind=task requires an EXACT ref (a
    # task UUID / finding hash), so the task case uses a real id.
    foundation_id = str(uuid.uuid4())
    for kind, ref in (("task", foundation_id), ("pr", "7910"), ("capability", "auth")):
        parsed = AgentStatusPayload(**base, blocked_need={"kind": kind, "ref": ref})
        assert parsed.blocked_need is not None
        assert parsed.blocked_need.kind == kind
        assert parsed.blocked_need.ref == ref

    # A finding-hash task ref is also exact and accepted.
    parsed_hash = AgentStatusPayload(
        **base, blocked_need={"kind": "task", "ref": "deadbeefcafe0001"}
    )
    assert parsed_hash.blocked_need.ref == "deadbeefcafe0001"

    parsed_upper = AgentStatusPayload(
        **base, blocked_need={"kind": "task", "ref": "DEADBEEFCAFE0001"}
    )
    assert parsed_upper.blocked_need.ref == "deadbeefcafe0001"

    parsed_uuid_upper = AgentStatusPayload(
        **base, blocked_need={"kind": "task", "ref": foundation_id.upper()}
    )
    assert parsed_uuid_upper.blocked_need.ref == foundation_id

    # Optional human label is accepted.
    with_label = AgentStatusPayload(
        **base,
        blocked_need={"kind": "task", "ref": foundation_id, "label": "the foundation"},
    )
    assert with_label.blocked_need.label == "the foundation"

    # A title-like kind=task ref is NOT an exact task ref — it is gracefully
    # DROPPED to None (identical to an absent need), so the BLOCKED status report
    # still succeeds rather than 422-ing the whole request. Named foundations
    # belong to kind=capability.
    dropped = AgentStatusPayload(
        **base, blocked_need={"kind": "task", "ref": "Build the auth subsystem"}
    )
    assert dropped.blocked_need is None
    dropped2 = AgentStatusPayload(**base, blocked_need={"kind": "task", "ref": "t-x"})
    assert dropped2.blocked_need is None

    # Malformed: unrecognized kind.
    with pytest.raises(ValidationError):
        AgentStatusPayload(**base, blocked_need={"kind": "branch", "ref": "main"})
    # Malformed: empty ref.
    with pytest.raises(ValidationError):
        AgentStatusPayload(**base, blocked_need={"kind": "task", "ref": ""})
    # Malformed: missing ref.
    with pytest.raises(ValidationError):
        AgentStatusPayload(**base, blocked_need={"kind": "task"})


