@pytest.mark.asyncio
async def test_post_commit_lock_on_retry_returns_pending_not_500(
    client: AsyncClient, db_session, mocker
):
    """A PostCommitLocked during the terminal-task post-commit RETRY path is pure
    row contention (the sweep or a peer instance holds the row and is running the
    same post-commit). It must NOT surface as a 500 — Cloud Run classifies any 5xx
    as a ContainerError and quarantines the instance. The endpoint must return a
    clean 200 ``post_commit_retry_pending`` and leave ``post_commit_pending`` set
    so the sweep keeps ownership of the deferred work.

    Regression guard for the root cause of the ``[3x] task_lifecycle.py:465 ->
    [2x] ContainerError`` orchestrator errors: PostCommitLocked is documented as
    a "retryable pending, not an error" but the retry path re-raised it as 500.
    """
    from app.task_lifecycle import PostCommitLocked

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=mocker.AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)
    pc = mocker.patch(
        "app.routers.agent_status._process_post_commit",
        new_callable=mocker.AsyncMock,
        side_effect=PostCommitLocked("task held by peer after 3 retries"),
    )

    project = Project(name="PostCommit Lock Test", user_id="test-user-pc-lock")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    # Terminal task with the write-ahead marker already set: this is exactly the
    # state the agent's HTTP retry hits when the original post-commit deferred its
    # side effects to the sweep.
    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "build x"}],
        vm_instance_id="agent-vm-pc-lock",
        status=TaskStatus.COMPLETED,
        post_commit_pending=True,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-pc-lock")
    headers = {"x-agent-token": token}
    payload = {"task_id": str(task.id), "status": "COMPLETED"}
    resp = await client.post("/api/agent/status", json=payload, headers=headers)

    assert resp.status_code == 200, (
        f"row contention must not 500 (Cloud Run flags 5xx as ContainerError); "
        f"got {resp.status_code}: {resp.text}"
    )
    assert resp.json().get("status") == "post_commit_retry_pending"
    pc.assert_awaited()  # the retry path actually attempted post-commit

    # The marker must remain set so _sweep_post_commit_pending still owns the retry.
    await db_session.refresh(task)
    assert task.post_commit_pending is True, (
        "post_commit_pending must stay set on contention — the sweep owns the retry"
    )


@pytest.mark.asyncio
async def test_exact_ended_resident_terminal_retry_drives_post_commit(
    client: AsyncClient, db_session, mocker
):
    """Cap/lapse ends the session before the agent's final status callback.

    The exact ended generation/incarnation may consume the server-owned pending
    marker, while the ordinary Resident authority fence remains closed.
    """
    from app.strategic_resident_session import RESIDENT_SESSION_KEY

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.broadcast.broadcast_to_project", new_callable=AsyncMock)
    process_post_commit = mocker.patch(
        "app.routers.agent_status._process_post_commit",
        new_callable=AsyncMock,
        return_value={"status": "accepted"},
    )

    project = Project(name="Ended Resident Retry", user_id="test-user-resident")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task_id = uuid.uuid4()
    incarnation_id = uuid.uuid4()
    session_id = "ended-resident-session"
    generation = 4
    task = Task(
        id=task_id,
        project_id=project.id,
        payloads=[{"type": "strategic_review", "resident_session": True}],
        vm_instance_id="runner:ended-resident",
        status=TaskStatus.COMPLETED,
        post_commit_pending=True,
        context={
            "_resident_session": True,
            "strategic_session_id": session_id,
            "_resident_worker_generation": generation,
            "_post_commit_pending_meta": {
                "reason": "resident_session_ended",
                "attempts": 0,
                "payload": {
                    "task_id": str(task_id),
                    "resident_incarnation_id": str(incarnation_id),
                    "status": "COMPLETED",
                    "artifact_type": "RESEARCH_FINDINGS",
                    "logs": "Canonical server-authored Resident completion",
                },
            },
        },
    )
    project.vision = {
        RESIDENT_SESSION_KEY: {
            "status": "ended",
            "stop_requested": True,
            "session_id": session_id,
            "task_id": str(task_id),
            "worker_generation": generation,
            "worker_incarnation_id": str(incarnation_id),
        }
    }
    db_session.add(project)
    db_session.add(task)
    await db_session.commit()

    token = create_agent_token(str(task.id), task.vm_instance_id)
    rejected = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task.id),
            "resident_incarnation_id": str(uuid.uuid4()),
            "status": "COMPLETED",
        },
        headers={"x-agent-token": token},
    )
    assert rejected.status_code == 409
    process_post_commit.assert_not_awaited()
    await db_session.refresh(task)
    assert task.post_commit_pending is True

    conflicting = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task.id),
            "resident_incarnation_id": str(incarnation_id),
            "status": "FAILED",
        },
        headers={"x-agent-token": token},
    )
    assert conflicting.status_code == 409
    process_post_commit.assert_not_awaited()
    await db_session.refresh(task)
    assert task.status == TaskStatus.COMPLETED
    assert task.post_commit_pending is True

    response = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task.id),
            "resident_incarnation_id": str(incarnation_id),
            "status": "COMPLETED",
            "logs": "Tampered callback content must not reach post-commit",
        },
        headers={"x-agent-token": token},
    )

    assert response.status_code == 200, response.text
    assert response.json()["status"] == "accepted"
    process_post_commit.assert_awaited_once()
    processed_payload = process_post_commit.await_args.args[1]
    assert processed_payload.status == TaskStatus.COMPLETED
    assert processed_payload.logs == "Canonical server-authored Resident completion"
    await db_session.refresh(task)
    assert task.post_commit_pending is False
    assert "_post_commit_pending_meta" not in (task.context or {})


@pytest.mark.asyncio
async def test_post_commit_disconnect_on_retry_returns_pending_not_500(
    client: AsyncClient, db_session, mocker
):
    """A disconnection-class DB error during the post-commit RETRY path is deploy-
    cutover collateral (a Cloud Run rollout drains the instance and severs the
    in-flight connection), not a code fault. It must NOT surface as a 500 — Cloud
    Run flags any 5xx as a ContainerError and quarantines the instance, which during
    a cutover would cascade. The endpoint must return a clean 200
    ``post_commit_retry_pending`` and leave ``post_commit_pending`` set so the sweep
    keeps ownership of the deferred work.

    Regression guard for the ``InterfaceError -> 500 -> ContainerError`` burst in the
    2026-06-03 07:38 cutover window.
    """
    from sqlalchemy.exc import InterfaceError

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=mocker.AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)
    pc = mocker.patch(
        "app.routers.agent_status._process_post_commit",
        new_callable=mocker.AsyncMock,
        side_effect=InterfaceError("SELECT 1", {}, Exception("connection is closed")),
    )

    project = Project(name="PostCommit Disc Test", user_id="test-user-pc-disc")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "build x"}],
        vm_instance_id="agent-vm-pc-disc",
        status=TaskStatus.COMPLETED,
        post_commit_pending=True,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-pc-disc")
    headers = {"x-agent-token": token}
    payload = {"task_id": str(task.id), "status": "COMPLETED"}
    resp = await client.post("/api/agent/status", json=payload, headers=headers)

    assert resp.status_code == 200, (
        f"cutover-collateral disconnect must not 500 (Cloud Run flags 5xx as "
        f"ContainerError); got {resp.status_code}: {resp.text}"
    )
    assert resp.json().get("status") == "post_commit_retry_pending"
    pc.assert_awaited()

    await db_session.refresh(task)
    assert task.post_commit_pending is True, (
        "post_commit_pending must stay set on disconnect — the sweep owns the retry"
    )


@pytest.mark.asyncio
async def test_post_commit_disconnect_inline_returns_pending_not_500(
    client: AsyncClient, db_session, mocker
):
    """The INLINE post-commit path (fresh terminal transition, no pre-existing
    marker) wraps _process_post_commit in asyncio.wait_for. A disconnection-class
    DB error there (the reported ``agent_status.py:3117 -> InterfaceError`` →
    ContainerError) must be treated like a deferred-retry, not re-raised as a 500:
    the early commit already persisted the terminal status and the write-ahead
    marker is set, so the sweep owns the side effects.
    """
    from sqlalchemy.exc import InterfaceError

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=mocker.AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)
    pc = mocker.patch(
        "app.routers.agent_status._process_post_commit",
        new_callable=mocker.AsyncMock,
        side_effect=InterfaceError("SELECT 1", {}, Exception("connection is closed")),
    )

    project = Project(name="PostCommit Disc Inline", user_id="test-user-pc-disc2")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    # Fresh, NON-terminal task: the status POST drives the inline post-commit path.
    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "build x"}],
        vm_instance_id="agent-vm-pc-disc2",
        status=TaskStatus.IN_PROGRESS,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-pc-disc2")
    headers = {"x-agent-token": token}
    payload = {"task_id": str(task.id), "status": "COMPLETED"}
    resp = await client.post("/api/agent/status", json=payload, headers=headers)

    assert resp.status_code == 200, (
        f"inline post-commit disconnect must not 500; got {resp.status_code}: {resp.text}"
    )
    assert resp.json().get("status") == "post_commit_retry_pending"
    pc.assert_awaited()

    # The write-ahead marker must be set so the sweep retries the deferred effects.
    await db_session.refresh(task)
    assert task.post_commit_pending is True


@pytest.mark.asyncio
async def test_agent_status_post_commit_resolves_engine_from_none_bind_session(
    client: AsyncClient, db_session, mocker
):
    import conftest as _testing_conftest
    from sqlalchemy.ext.asyncio import AsyncSession as _AS, async_sessionmaker

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.broadcast.broadcast_to_project", new_callable=AsyncMock)

    async def _process_post_commit(task_id, _payload, _session_factory):
        async with _session_factory() as session:
            assert await session.get(Task, task_id), (
                "resolved post-commit session factory must load the task even "
                "when the request session exposes bind=None"
            )
        return {"status": "accepted", "task_id": str(task_id)}

    mocker.patch(
        "app.routers.agent_status._process_post_commit",
        new_callable=AsyncMock,
        side_effect=_process_post_commit,
    )

    project = Project(name="None Bind Post Commit", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    factory = async_sessionmaker(
        _testing_conftest.engine, class_=_AS, expire_on_commit=False
    )

    class _NoneBindSession:
        bind = None

        def __init__(self, session):
            self._session = session

        def get_bind(self, *args, **kwargs):
            return _testing_conftest.engine

        def __getattr__(self, name):
            return getattr(self._session, name)

    async def _override_get_session():
        async with factory() as session:
            yield _NoneBindSession(session)

    app.dependency_overrides[get_session] = _override_get_session
    try:
        task = Task(
            project_id=project.id,
            payloads=[{"type": "create", "prompt": "build"}],
            vm_instance_id="agent-vm-inline",
            status=TaskStatus.IN_PROGRESS,
        )
        db_session.add(task)
        await db_session.commit()

        token = create_agent_token(str(task.id), task.vm_instance_id)
        headers = {"x-agent-token": token}
        payload = {"task_id": str(task.id), "status": "COMPLETED"}
        resp = await client.post("/api/agent/status", json=payload, headers=headers)
        assert resp.status_code == 200
        assert resp.json()["status"] == "accepted"
        await db_session.refresh(task)
        assert task.post_commit_pending is False

        task.post_commit_pending = True
        db_session.add(task)
        await db_session.commit()
        resp = await client.post("/api/agent/status", json=payload, headers=headers)
        assert resp.status_code == 200
        assert resp.json()["status"] == "accepted"
        await db_session.refresh(task)
        assert task.post_commit_pending is False
    finally:
        app.dependency_overrides.pop(get_session, None)


@pytest.mark.asyncio
@pytest.mark.parametrize(
    "requested_model", ["gemini-3.1-pro-preview", "gemini-3-pro-preview"]
)
async def test_external_api_provider_model_config_falls_back_without_backoff(
    requested_model, client: AsyncClient, db_session, mocker
):
    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=True)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=mocker.AsyncMock)
    mocker.patch(
        "app.routers.agent_status.release_max_plan_account",
        new_callable=mocker.AsyncMock,
    )
    mocker.patch(
        "app.routers.agent_status.broadcast_to_project", new_callable=mocker.AsyncMock
    )

    project = Project(
        name="Gemini Model Fallback Test", user_id="test-user-gemini-fallback"
    )
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    # Audit W1: retry_after_until is a column. Set it on the task directly.
    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "test", "model": requested_model}],
        vm_instance_id="agent-vm-gemini-model-config",
        status=TaskStatus.IN_PROGRESS,
        retry_after_until=datetime(2026, 4, 25),
        context={
            "llm_account_id": "gemini-acct-1",
            "max_plan_account_id": "gemini-acct-1",
            "llm_provider": "gemini",
            "llm_auth_mode": "api_key",
            "llm_model": requested_model,
            "llm_execution_mode": "default",
            "_api_failure_retries": 2,
            "blacklisted_accounts": ["gemini-acct-1"],
        },
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-gemini-model-config")
    resp = await client.post(
        "/api/agent/status",
        headers={"x-agent-token": token},
        json={
            "task_id": str(task.id),
            "status": "FAILED",
            "failure_category": "fatal",
            "logs": "ModelNotFoundError: models/gemini-3.1-pro-preview is not found for API version v1beta",
        },
    )
    assert resp.status_code == 200

    await db_session.refresh(task)
    assert task.status == TaskStatus.QUEUED
    assert task.payloads[0]["model"] == "gemini-2.5-pro"
    ctx = task.context or {}
