    diff_summary = [
        {
            "file": "backend/app/models.py",
            "additions": 45,
            "deletions": 12,
            "change_type": "modified",
        },
        {
            "file": "backend/testing/test_models.py",
            "additions": 30,
            "deletions": 0,
            "change_type": "added",
        },
    ]
    self_review_outcome = {
        "issues_found": False,
        "fixes_applied": False,
        "categories": [],
    }
    test_failure_summary = "FAILED backend/testing/test_models.py::test_create"

