# ---------------------------------------------------------------------------
# OAuth credential rotation (agent → backend)
# ---------------------------------------------------------------------------


async def _make_openai_oauth_task(db_session) -> tuple[Task, MaxPlanAccount, Project]:
    project = Project(name="Codex Rotate Test", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    account = MaxPlanAccount(
        user_id="test-user-123",
        name="codex-oauth",
        provider=LLMProviderName.OPENAI,
        auth_mode=LLMAuthMode.OAUTH,
        secret_blob_ref='{"tokens":{"access_token":"old","refresh_token":"rt-old"}}',
    )
    db_session.add(account)
    await db_session.commit()
    await db_session.refresh(account)

    task = Task(
        project_id=project.id,
        payloads=[{"cmd": "run"}],
        vm_instance_id="agent-vm-rotate",
        status=TaskStatus.IN_PROGRESS,
        context={
            "llm_account_id": str(account.id),
            "llm_provider": "openai",
            "llm_auth_mode": "oauth",
        },
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)
    return task, account, project


def _vm_token_without_project(vm_instance_id: str) -> str:
    import jwt as _jwt
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz

    from app.auth import AGENT_JWT_ALGORITHM, AGENT_JWT_SECRET, VM_SCOPED_TOKEN_SCOPE

    now = _dt.now(_tz.utc)
    return _jwt.encode(
        {
            "token_scope": VM_SCOPED_TOKEN_SCOPE,
            "vm_instance_id": vm_instance_id,
            "exp": now + _td(hours=8),
            "iat": now,
        },
        AGENT_JWT_SECRET,
        algorithm=AGENT_JWT_ALGORITHM,
    )


@pytest.mark.asyncio
async def test_rotate_credentials_updates_openai_oauth_secret(
    client: AsyncClient, db_session, mocker
):
    mocker.patch(
        "app.secrets_manager.store_user_secret",
        new=AsyncMock(return_value="projects/test/secrets/rotate/versions/2"),
    )
    task, account, _ = await _make_openai_oauth_task(db_session)

    token = create_agent_token(str(task.id), "agent-vm-rotate")
    new_blob = '{"tokens":{"access_token":"fresh","refresh_token":"rt-fresh"}}'
    res = await client.post(
        "/api/agent/credentials/rotate",
        headers={"x-agent-token": token},
        json={
            "secret": new_blob,
            "base_hash": hashlib.sha256(
                b'{"tokens":{"access_token":"old","refresh_token":"rt-old"}}'
            ).hexdigest(),
        },
    )

    assert res.status_code == 200, res.text
    assert res.json() == {"rotated": True}

    await db_session.refresh(account)
    from app.field_encryption import decrypt_field

    # secret_blob_ref is Fernet-encrypted at rest; the Postgres CI shard sets
    # the encryption key (SQLite runs are keyless passthrough), so assert the
    # decrypted plaintext, not the raw ciphertext column.
    assert (
        decrypt_field(account.secret_blob_ref)
        == "projects/test/secrets/rotate/versions/2"
    )


@pytest.mark.asyncio
async def test_rotate_credentials_stale_writer_adopts_winner_without_overwrite(
    client: AsyncClient, db_session, mocker
):
    old_blob = '{"tokens":{"access_token":"old","refresh_token":"rt-old"}}'
    winner_blob = '{"tokens":{"access_token":"winner","refresh_token":"rt-winner"}}'
    loser_blob = '{"tokens":{"access_token":"loser","refresh_token":"rt-loser"}}'
    old_hash = hashlib.sha256(old_blob.encode("utf-8")).hexdigest()
    store_secret = mocker.patch(
        "app.secrets_manager.store_user_secret",
        new=AsyncMock(return_value="projects/test/secrets/rotate-cas/versions/2"),
    )
    mocker.patch(
        "app.secrets_manager.get_user_secret",
        new=AsyncMock(return_value=winner_blob),
    )
    task, account, _ = await _make_openai_oauth_task(db_session)
    token = create_agent_token(str(task.id), "agent-vm-rotate")

    winner = await client.post(
        "/api/agent/credentials/rotate",
        headers={"x-agent-token": token},
        json={"secret": winner_blob, "base_hash": old_hash},
    )
    assert winner.status_code == 200, winner.text
    assert winner.json() == {"rotated": True}

    stale = await client.post(
        "/api/agent/credentials/rotate",
        headers={"x-agent-token": token},
        json={"secret": loser_blob, "base_hash": old_hash},
    )
    assert stale.status_code == 200, stale.text
    assert stale.json() == {
        "rotated": False,
        "reason": "stale_credential",
        "secret": winner_blob,
    }
    store_secret.assert_awaited_once()
    await db_session.refresh(account)
    from app.field_encryption import decrypt_field

    assert (
        decrypt_field(account.secret_blob_ref)
        == "projects/test/secrets/rotate-cas/versions/2"
    )


