@pytest.mark.asyncio
async def test_next_role_claims_warm_pinned_queued_task(
    client: AsyncClient, db_session, mocker
):
    """next-role atomically claims a QUEUED task whose context.warm_target_vm_id matches."""
    from datetime import timedelta

    project = Project(name="Next-Role Claim", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)
    fix_target = _mock_open_pr_execution_fence(mocker, project.id, 1234)

    prior_task = Task(
        project_id=project.id,
        payloads=[{"type": "review", "pr_number": 1234}],
        vm_instance_id="agent-vm-warm-claim",
        status=TaskStatus.COMPLETED,
    )
    db_session.add(prior_task)
    # A QUEUED fix pinned to the same VM
    deadline = (_utcnow() + timedelta(seconds=240)).isoformat()
    pinned_task = Task(
        project_id=project.id,
        payloads=[{"type": "fix", "pr_number": 1234, "branch": "feat/x"}],
        vm_instance_id=None,
        status=TaskStatus.QUEUED,
        context={
            "warm_target_vm_id": "agent-vm-warm-claim",
            "warm_target_pr": "1234",
            "warm_handoff_deadline": deadline,
            "review_loop": {"fix_target": fix_target},
        },
    )
    db_session.add(pinned_task)
    await db_session.commit()
    await db_session.refresh(prior_task)
    await db_session.refresh(pinned_task)

    token = create_agent_token(str(prior_task.id), "agent-vm-warm-claim")
    resp = await client.post(
        "/api/agent/next-role",
        json={
            "vm_instance_id": "agent-vm-warm-claim",
            "prior_task_id": str(prior_task.id),
            "prior_pr_number": 1234,
        },
        headers={"x-agent-token": token},
    )
    assert resp.status_code == 200
    body = resp.json()
    assert body["action"] == "claim"
    assert body["task_id"] == str(pinned_task.id)
    assert body["warm_start"] is True
    # New JWT scoped to the warm-claimed task is included so the agent
    # can authenticate subsequent task-scoped calls (the prior task's
    # JWT is terminal and only authenticates the idempotent
    # next-role/vm-heartbeat paths).
    assert isinstance(body.get("agent_token"), str) and body["agent_token"]
    from app.auth import verify_agent_jwt

    new_claims = verify_agent_jwt(body["agent_token"])
    assert new_claims["sub"] == str(pinned_task.id)
    assert new_claims["vm_instance_id"] == "agent-vm-warm-claim"
    assert new_claims["project_id"] == str(project.id)
    assert new_claims["task_type"] == "fix"

    await db_session.refresh(pinned_task)
    assert pinned_task.status == TaskStatus.IN_PROGRESS
    assert pinned_task.vm_instance_id == "agent-vm-warm-claim"
    assert (pinned_task.context or {}).get("_timing", {}).get("warm_start") is True
    assert (pinned_task.context or {}).get("_timing", {}).get(
        "prior_role_vm_id"
    ) == "agent-vm-warm-claim"


@pytest.mark.asyncio
@pytest.mark.parametrize("advertise_contract", [True, False])
async def test_next_role_research_contract_capability_handshake(
    client: AsyncClient,
    db_session,
    advertise_contract: bool,
):
    """The authoritative warm claim negotiates strict output per attempt."""
    project = Project(
        name=f"Warm Research Contract {advertise_contract}",
        user_id="test-user-123",
    )
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    vm_id = f"agent-vm-warm-research-contract-{advertise_contract}"
    prior_task = Task(
        project_id=project.id,
        payloads=[{"type": "review"}],
        vm_instance_id=vm_id,
        status=TaskStatus.COMPLETED,
    )
    pinned_task = Task(
        project_id=project.id,
        payloads=[
            {"type": "research", "prompt": "Inspect the bounded direction"}
        ],
        status=TaskStatus.QUEUED,
        # Seed a prior-attempt marker to prove a stale claimant clears it.
        context={
            "warm_target_vm_id": vm_id,
            "warm_handoff_deadline": (
                _utcnow() + timedelta(seconds=240)
            ).isoformat(),
            "research_output_contract_version": 2,
        },
    )
    db_session.add_all([prior_task, pinned_task])
    await db_session.commit()
    await db_session.refresh(prior_task)

    token = create_agent_token(str(prior_task.id), vm_id)
    headers = {"x-agent-token": token}
    if advertise_contract:
        headers["x-research-output-contract-version"] = "2"
    response = await client.post(
        "/api/agent/next-role",
        json={"vm_instance_id": vm_id, "prior_task_id": str(prior_task.id)},
        headers=headers,
    )

    assert response.status_code == 200
    await db_session.refresh(pinned_task)
    if advertise_contract:
        assert pinned_task.context["research_output_contract_version"] == 2
    else:
        assert "research_output_contract_version" not in (pinned_task.context or {})

    # The warm response issues the task-scoped token; the agent's immediate
    # /claim call is an idempotent replay and must expose, but never renegotiate,
    # the contract selected by /next-role.
    replay_headers = {"x-agent-token": response.json()["agent_token"]}
    if advertise_contract:
        replay_headers["x-research-output-contract-version"] = "2"
    replay = await client.post("/api/agent/claim", headers=replay_headers)
    assert replay.status_code == 200
    if advertise_contract:
        assert replay.json()["context"]["research_output_contract_version"] == 2
    else:
        assert "research_output_contract_version" not in replay.json()["context"]


@pytest.mark.asyncio
async def test_next_role_publishes_backend_owned_no_workspace_capability(
    client: AsyncClient, db_session
):
    """Warm memory tasks tell the agent to skip repository reset before running."""
    from datetime import timedelta

    project = Project(name="Next-Role Memory Capability", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    vm_id = "agent-vm-memory-capability"
    prior_task = Task(
        project_id=project.id,
        payloads=[{"type": "review", "pr_number": 1}],
        vm_instance_id=vm_id,
        status=TaskStatus.COMPLETED,
    )
    pinned_task = Task(
        project_id=project.id,
        payloads=[{"type": "memory_consolidation", "job_id": str(uuid.uuid4())}],
        status=TaskStatus.QUEUED,
        context={
            "warm_target_vm_id": vm_id,
            "warm_handoff_deadline": (_utcnow() + timedelta(seconds=240)).isoformat(),
        },
    )
    db_session.add_all([prior_task, pinned_task])
    await db_session.commit()
    await db_session.refresh(prior_task)

    token = create_agent_token(str(prior_task.id), vm_id)
    resp = await client.post(
        "/api/agent/next-role",
        json={"vm_instance_id": vm_id, "prior_task_id": str(prior_task.id)},
        headers={"x-agent-token": token},
    )

    assert resp.status_code == 200
    assert resp.json()["workspace_requirement"] == "none"


@pytest.mark.asyncio
async def test_next_role_respects_retry_after_for_warm_pinned_task(
    client: AsyncClient, db_session
):
    """Warm-claim must not bypass retry_after_until on a parked/pinned task."""
    project = Project(name="Next-Role Retry-After", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    prior_task = Task(
        project_id=project.id,
        payloads=[{"type": "review", "pr_number": 5555}],
        vm_instance_id="agent-vm-retry-after",
        status=TaskStatus.COMPLETED,
    )
    db_session.add(prior_task)
    pinned_task = Task(
        project_id=project.id,
        payloads=[{"type": "fix", "pr_number": 5555}],
        status=TaskStatus.QUEUED,
        retry_after_until=_utcnow() + timedelta(minutes=5),
        context={
            "warm_target_vm_id": "agent-vm-retry-after",
            "warm_target_pr": "5555",
        },
    )
    db_session.add(pinned_task)
    await db_session.commit()
    await db_session.refresh(prior_task)
    await db_session.refresh(pinned_task)

    token = create_agent_token(str(prior_task.id), "agent-vm-retry-after")
    resp = await client.post(
        "/api/agent/next-role",
        json={
            "vm_instance_id": "agent-vm-retry-after",
            "prior_task_id": str(prior_task.id),
            "prior_pr_number": 5555,
        },
        headers={"x-agent-token": token},
    )
    assert resp.status_code == 204

    await db_session.refresh(pinned_task)
    assert pinned_task.status == TaskStatus.QUEUED
    assert pinned_task.vm_instance_id is None


@pytest.mark.asyncio
async def test_next_role_defers_parked_task_when_retarget_has_no_account(
    client: AsyncClient, db_session, mocker
):
    """A parked task must stay queued when retarget can't resolve an account."""
    from types import SimpleNamespace
    from app.shared_state import runtime_config as _runtime_config

    project = Project(name="Next-Role Parked Retarget", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    prior_task = Task(
        project_id=project.id,
        payloads=[{"type": "review", "pr_number": 6666}],
        vm_instance_id="agent-vm-parked-retarget",
        status=TaskStatus.COMPLETED,
    )
    db_session.add(prior_task)
    pinned_task = Task(
        project_id=project.id,
        payloads=[{"type": "fix", "pr_number": 6666}],
        status=TaskStatus.QUEUED,
        retry_after_until=_utcnow() - timedelta(minutes=1),
        context={
            "warm_target_vm_id": "agent-vm-parked-retarget",
            "warm_target_pr": "6666",
            "parked_for_retarget": True,
            "park_deadline": (_utcnow() + timedelta(minutes=5)).isoformat(),
            "blacklisted_accounts": ["acct-failed"],
        },
    )
    db_session.add(pinned_task)
    await db_session.commit()
    await db_session.refresh(prior_task)
    await db_session.refresh(pinned_task)

    mocker.patch(
        "app.max_plan_pool.select_llm_runtime_for_task",
        return_value=SimpleNamespace(
            provider="anthropic",
            auth_mode="oauth",
            model="claude-sonnet-4-6",
            quality_tier=None,
            account=None,
            settings=None,
            execution_mode=None,
        ),
    )
    mocker.patch.dict(
        _runtime_config,
        {
            "warm_retarget_enabled": True,
            "warm_continuity_enabled": True,
        },
        clear=False,
    )

    token = create_agent_token(str(prior_task.id), "agent-vm-parked-retarget")
    resp = await client.post(
        "/api/agent/next-role",
        json={
            "vm_instance_id": "agent-vm-parked-retarget",
            "prior_task_id": str(prior_task.id),
            "prior_pr_number": 6666,
        },
        headers={"x-agent-token": token},
    )
    assert resp.status_code == 204

    await db_session.refresh(pinned_task)
    assert pinned_task.status == TaskStatus.QUEUED
    assert pinned_task.vm_instance_id is None
    ctx = pinned_task.context or {}
    assert ctx.get("parked_for_retarget") is True
    assert ctx.get("blacklisted_accounts") == ["acct-failed"]


@pytest.mark.asyncio
async def test_next_role_returns_204_when_warm_continuity_suppressed(
    client: AsyncClient, db_session, mocker
):
    """Circuit breaker: next-role returns 204 (skipping warm claim) when
    is_warm_continuity_suppressed() returns True, even if a pinned QUEUED task exists."""
    from datetime import timedelta

    project = Project(name="Next-Role CB Suppressed", user_id="test-user-123")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    prior_task = Task(
        project_id=project.id,
        payloads=[{"type": "review"}],
        vm_instance_id="agent-vm-cb-suppressed",
        status=TaskStatus.COMPLETED,
    )
    db_session.add(prior_task)
    deadline = (_utcnow() + timedelta(seconds=240)).isoformat()
    pinned_task = Task(
        project_id=project.id,
        payloads=[{"type": "fix", "pr_number": 9999}],
        status=TaskStatus.QUEUED,
        context={
            "warm_target_vm_id": "agent-vm-cb-suppressed",
            "warm_handoff_deadline": deadline,
        },
    )
    db_session.add(pinned_task)
    await db_session.commit()
    await db_session.refresh(prior_task)
    await db_session.refresh(pinned_task)

    mocker.patch("app.shared_state.is_warm_continuity_suppressed", return_value=True)

    token = create_agent_token(str(prior_task.id), "agent-vm-cb-suppressed")
    resp = await client.post(
        "/api/agent/next-role",
        json={
            "vm_instance_id": "agent-vm-cb-suppressed",
            "prior_task_id": str(prior_task.id),
        },
        headers={"x-agent-token": token},
    )
    assert resp.status_code == 204

    await db_session.refresh(pinned_task)
    assert pinned_task.status == TaskStatus.QUEUED, (
        "Circuit breaker must not claim the pinned task"
    )


@pytest.mark.asyncio
async def test_next_role_refuses_warm_claim_on_doomed_vm(
    client: AsyncClient, db_session
):
    """Race guard: when a sibling task's agent_completion fired
    fire_and_forget_vm_delete, the VM is alive in GCP for ~30-60s but
    the delete is in flight. Without this guard, next-role races into
    that window, claims the doomed VM, and the agent gets SIGTERM'd
    mid-task. Production 2026-05-05 task cfd73cec on VM c44258 hit
    exactly this — claimed warm VM that was already scheduled for
    delete by 41456ba8's agent_completion 9s earlier; SIGTERM landed
    ~50s later as the GCP delete completed."""
    from datetime import timedelta
    from app.vm_lifecycle import _orchestrator_deleted_vms
    import time

    project = Project(name="Next-Role Doomed-VM", user_id="test-user-doomed")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    prior_task = Task(
        project_id=project.id,
        payloads=[{"type": "fix", "pr_number": 4321}],
        vm_instance_id="agent-vm-doomed",
        status=TaskStatus.COMPLETED,
    )
    db_session.add(prior_task)
    deadline = (_utcnow() + timedelta(seconds=240)).isoformat()
    pinned_task = Task(
        project_id=project.id,
        payloads=[{"type": "review", "pr_number": 4321, "branch": "feat/y"}],
        vm_instance_id=None,
        status=TaskStatus.QUEUED,
        context={
            "warm_target_vm_id": "agent-vm-doomed",
            "warm_target_pr": "4321",
            "warm_handoff_deadline": deadline,
        },
    )
    db_session.add(pinned_task)
    await db_session.commit()
    await db_session.refresh(prior_task)
    await db_session.refresh(pinned_task)

    # Mark the VM as orchestrator-scheduled-for-delete. This is the
    # synchronous marker that fire_and_forget_vm_delete records before
    # scheduling the background GCP call.
    _orchestrator_deleted_vms["agent-vm-doomed"] = (time.time(), "agent_completion")
    try:
        token = create_agent_token(str(prior_task.id), "agent-vm-doomed")
        resp = await client.post(
            "/api/agent/next-role",
            json={
                "vm_instance_id": "agent-vm-doomed",
                "prior_task_id": str(prior_task.id),
                "prior_pr_number": 4321,
            },
            headers={"x-agent-token": token},
        )
        # 204 = no warm-claim (treat doomed VM as if no warm task were
        # available so the agent exits cleanly).
        assert resp.status_code == 204, (
            f"expected 204 on doomed-VM warm-claim attempt, got {resp.status_code} — "
            f"the QUEUED task was claimed onto a VM that's about to die"
        )

        # The pinned task must remain QUEUED so the orchestrator can
        # provision a fresh VM for it on the next dispatch tick.
        await db_session.refresh(pinned_task)
        assert pinned_task.status == TaskStatus.QUEUED
        assert pinned_task.vm_instance_id is None
    finally:
        _orchestrator_deleted_vms.pop("agent-vm-doomed", None)


