@pytest.mark.asyncio
async def test_legacy_qualifier_smoketest_artifact_is_stored_but_inert(
    client: AsyncClient, db_session, mocker
):
    """A legacy SMOKETEST_RESULT posted at terminal status is stored but inert.

    The historical qualifier marker still suppresses ordinary task-repair
    handling and may wake finalization, while the artifact itself must never be
    loaded into the active score or reintroduce the retired smoke gate.
    """
    import json as _json
    from app import release_version as _rv
    from app.release_qualifier import (
        _qualification_contract_fingerprint,
        _rubric_fingerprint,
        _snapshot_qualification_rubric,
    )
    from app.models import ReleaseVersion, Artifact, ArtifactType

    mocker.patch("app.vm_lifecycle.delete_agent_vm", return_value=None)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=AsyncMock)
    mocker.patch("app.vm_lifecycle.fire_and_forget_vm_delete", return_value=None)
    mocker.patch("app.broadcast.broadcast_to_project", new_callable=AsyncMock)
    # Post-finalize strategic hooks make real GitHub calls that hang on the
    # network-isolated harness; neutralize them (outside this test's contract).
    mocker.patch(
        "app.release_qualifier._maybe_trigger_strategic_after_qualification",
        new=AsyncMock(return_value=None),
    )
    mocker.patch(
        "app.release_qualifier._maybe_reconcile_after_promotion_conflict",
        new=AsyncMock(return_value=None),
    )
    # Finalize re-resolves CI for the candidate commit rather than trusting the
    # spawn-time ci_green snapshot; with no GitHub credentials in this test that
    # resolution degrades to not-green and would hard-block on ci_not_green.
    # This test's subject is smoketest-artifact visibility (CI is assumed green,
    # as the stored qualification records), so pin the re-resolution to green.
    mocker.patch(
        "app.release_qualifier._resolve_ci_at_finalize",
        new=AsyncMock(
            return_value=(
                True,
                {
                    "state": "green",
                    "resolved_sha": "deadbeef",
                    "detail": "pinned-green",
                },
            )
        ),
    )
    candidate_sha = "abcd" * 10
    # Candidate authorship is an independent live gate. Keep this legacy
    # smoketest-artifact test isolated with a valid, clean candidate-range
    # measurement rather than asserting away unrelated blockers.
    mocker.patch(
        "app.release_qualifier._measure_candidate_operator_authorship",
        new=AsyncMock(
            return_value={
                "state": "resolved",
                "count": 0,
                "offenders": [],
                "range": {"base_sha": "a" * 40, "head_sha": candidate_sha},
            }
        ),
    )
    mocker.patch(
        "app.release_qualifier.candidate_authorship_range",
        return_value=("a" * 40, candidate_sha),
    )
    mocker.patch(
        "app.release_commit_authorship.candidate_authorship_range",
        return_value=("a" * 40, candidate_sha),
    )
    # promotion_enabled defaults False (dark) — a confident candidate dry-runs.

    project = Project(
        name="Qualifier-Flush-Regression",
        user_id="qualifier-user",
        github_owner="acme",
        github_repo="widget",
    )
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)
    version = await _rv.open_version(db_session, project.id, version_number=1)
    db_session.add(
        VersionAcceptanceCriterion(
            project_id=project.id,
            release_version_id=version.id,
            criterion_key="c-test-operator-authorship",
            text="test fixture declares candidate authorship budget",
            created_by="test",
            evidence_contract={
                "type": "operator_authored_commits",
                "predicate": {"max_count": 0},
            },
            evidence_contract_updated_by="test",
        )
    )
    await db_session.commit()
    await db_session.refresh(version)

    # The active release audit already completed with a clean report.
    audit_task = Task(
        project_id=project.id,
        title="Release audit child",
        payloads=[{"type": "release_audit", "base_branch": "main"}],
        vm_instance_id="agent-vm-audit-flush",
        status=TaskStatus.COMPLETED,
        context={"release_version_id": str(version.id)},
    )
    db_session.add(audit_task)
    await db_session.commit()
    await db_session.refresh(audit_task)
    db_session.add(
        Artifact(
            task_id=audit_task.id,
            artifact_type=ArtifactType.RELEASE_AUDIT_REPORT,
            logs=_json.dumps(
                {
                    "audit_score": 1.0,
                    "test_erosion": {
                        "deleted_test_files": [],
                        "test_count_delta": 0,
                        "assertion_delta": 0,
                    },
                    "findings": [],
                }
            ),
        )
    )
    await db_session.commit()

    # A legacy qualifier-smoketest is IN_PROGRESS and about to post its archival
    # result through the ordinary agent endpoint.
    smoke_task = Task(
        project_id=project.id,
        title="Qualifier smoketest child",
        payloads=[{"type": "smoketest", "base_branch": "automain"}],
        vm_instance_id="agent-vm-smoke-flush",
        status=TaskStatus.IN_PROGRESS,
        context={
            "release_version_id": str(version.id),
            "qualifier_smoketest": True,
        },
    )
    db_session.add(smoke_task)
    await db_session.commit()
    await db_session.refresh(smoke_task)

    rubric_snapshot, rubric_lifecycle_snapshot = await _snapshot_qualification_rubric(
        db_session, version
    )
    rubric_fingerprint = _rubric_fingerprint(rubric_snapshot)
    version.last_qualification = {
        "status": "pending",
        # Real run_qualification always stamps the launched rubric projection;
        # #15102 made _finalize_qualification resolve it first and short-circuit
        # to rubric_provenance_unknown when it is absent. Mirror the active
        # release rubric so the archival-artifact path is reached as in prod.
        "rubric_snapshot": rubric_snapshot,
        "rubric_fingerprint": rubric_fingerprint,
        "contract_fingerprint": _qualification_contract_fingerprint(
            version.goal or "", rubric_fingerprint
        ),
        "version_goal": version.goal or "",
        "rubric_lifecycle_snapshot": rubric_lifecycle_snapshot,
        "candidate_sha": candidate_sha,
        "ci_green": True,
        "started_at": "2026-05-20T00:00:00",
        "audit_task_id": str(audit_task.id),
        "smoketest_task_id": str(smoke_task.id),
    }
    db_session.add(version)
    await db_session.commit()

    # The smoketest passes every test — a healthy candidate.
    smoketest_result = {
        "passed": True,
        "tests": [
            {"name": "startup_probe", "status": "pass"},
            {"name": "login_flow", "status": "pass"},
        ],
        "suites": {
            "startup": {"passed": True, "tests": []},
            "curated": {"passed": True, "tests": []},
        },
    }
    token = create_agent_token(str(smoke_task.id), "agent-vm-smoke-flush")
    resp = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(smoke_task.id),
            "status": "COMPLETED",
            "artifact_type": "SMOKETEST_RESULT",
            "logs": _json.dumps(smoketest_result),
        },
        headers={"x-agent-token": token},
    )
    assert resp.status_code == 200

    async with _process_post_commit_factory(db_session)() as fresh:
        refetched = await fresh.get(ReleaseVersion, version.id)
        qual = refetched.last_qualification or {}
        archival_artifact = await fresh.scalar(
            select(Artifact).where(
                Artifact.task_id == smoke_task.id,
                Artifact.artifact_type == ArtifactType.SMOKETEST_RESULT,
            )
        )

    assert archival_artifact is not None
    # Finalization ran, but the archival artifact is absent from active scoring.
    assert qual.get("status") != "pending", f"version left wedged: {qual}"
    assert qual.get("blocker") is None, (
        f"archival smoketest wrongly hard-blocked the candidate: {qual}"
    )
    assert "smoketest" not in qual.get("sub_scores", {})
    # Promotion ships dark (promotion_enabled False) → dry-run, not promoted.
    assert qual.get("status") == "dry_run"


