# ---------------------------------------------------------------------------
# Account-state-correlated RATE_LIMIT requeue tests (cluster 2/4)
# ---------------------------------------------------------------------------


@pytest.mark.asyncio
async def test_generic_failure_ignores_unrelated_account_cooldown_and_burns_retry(
    client: AsyncClient, db_session, mocker
):
    """A generic failure cannot borrow RATE_LIMIT from ambient account cooldown.

    Only direct provider/runtime evidence authorizes a free rate-limit requeue;
    without it, the failure remains CODE_ERROR and consumes a normal retry.
    """
    from app.time_utils import _utcnow
    import app.max_plan_pool as pool_mod

    account_id = "aaaaaaaa-0001-4000-a000-000000000001"
    # Account disabled 5 minutes ago (hits=1 → 30-min cooldown → still cooling).
    # Use naive _utcnow() to match the production data shape: max_plan_pool stores
    # disabled_models[...]['at'] as a NAIVE datetime, so the fixture must too —
    # otherwise the test passes against an aware value the live pool never produces.
    at = _utcnow() - timedelta(minutes=5)
    fake_pool = {
        account_id: {
            "id": account_id,
            "name": "test-account-rl-corr",
            "active_tasks": 1,
            "disabled_models": {
                "claude-sonnet-4-6": {
                    "at": at,
                    "hits": 1,
                    "kind": "rate_limit",
                }
            },
        }
    }
    mocker.patch.object(pool_mod, "_account_by_id", fake_pool)
    mocker.patch("app.vm_lifecycle._ensure_vm_deleted", new_callable=mocker.AsyncMock)
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)

    project = Project(name="RL Account Corr Test", user_id="test-user-rl-corr-001")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "test task"}],
        vm_instance_id="agent-vm-rl-corr-001",
        status=TaskStatus.IN_PROGRESS,
        context={"llm_account_id": account_id, "llm_model": "claude-sonnet-4-6"},
        attempt_count=0,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)
    task_id_str = str(task.id)

    token = create_agent_token(task_id_str, "agent-vm-rl-corr-001")
    # Generic failure — no rate-limit keywords or explicit provider signal. The
    # separate account cooldown is not evidence about this task's failure.
    payload = {
        "task_id": task_id_str,
        "status": "FAILED",
        "failure_category": "claude_code_failed",
        "logs": "Process exited with code 1",
    }
    resp = await client.post(
        "/api/agent/status", json=payload, headers={"x-agent-token": token}
    )
    assert resp.status_code == 200

    await db_session.refresh(task)
    assert task.status == TaskStatus.QUEUED, (
        f"Retryable CODE_ERROR should requeue to QUEUED, got {task.status}"
    )
    assert task.attempt_count == 1, (
        f"generic CODE_ERROR must burn one retry, got {task.attempt_count}"
    )
    # Fresh-attempt reset intentionally removes the prior attempt's normalized
    # failure category; the retry debit is the durable classification signal.


@pytest.mark.asyncio
async def test_rate_limit_parks_and_retains_vm_when_alternate_account_eligible(
    client: AsyncClient, db_session, mocker
):
    """Flagged park-and-retarget keeps the warm VM when another same-pool
    account is already eligible, preserving the free RATE_LIMIT requeue
    semantics while blacklisting the failed account."""
    from app.time_utils import _utcnow
    from app.shared_state import runtime_config as _runtime_config
    import app.max_plan_pool as pool_mod

    failed_account_id = "aaaaaaaa-0001-4000-a000-00000000park"
    alternate_account_id = "aaaaaaaa-0001-4000-a000-00000000alt1"
    failed = {
        "id": failed_account_id,
        "user_id": "u-park",
        "name": "failed-account",
        "enabled": True,
        "active_tasks": 1,
        "oauth_token": "sk-ant-failed",
        "disabled_models": {
            "claude-sonnet-4-6": {"at": _utcnow() - timedelta(minutes=5), "hits": 1}
        },
    }
    alternate = {
        "id": alternate_account_id,
        "user_id": "u-park",
        "name": "alternate-account",
        "enabled": True,
        "active_tasks": 0,
        "oauth_token": "sk-ant-alt",
        "disabled_models": {},
    }
    mocker.patch.object(
        pool_mod,
        "_account_by_id",
        {failed_account_id: failed, alternate_account_id: alternate},
    )
    mocker.patch.object(pool_mod, "_max_plan_pools", {"u-park": [failed, alternate]})
    mocker.patch(
        "app.routers.agent_status.release_max_plan_account", new_callable=AsyncMock
    )
    mocker.patch(
        "app.routers.agent_status.disable_account_model", new_callable=AsyncMock
    )
    delete_vm = mocker.patch(
        "app.vm_lifecycle._ensure_vm_deleted", new_callable=AsyncMock
    )
    mocker.patch("app.broadcast.broadcast_to_project", return_value=None)
    mocker.patch.dict(
        _runtime_config,
        {
            "park_and_retarget_enabled": True,
            "park_and_retarget_budget_seconds": 600,
            "warm_continuity_enabled": True,
            "warm_retarget_enabled": True,
        },
        clear=False,
    )

    project = Project(name="Park And Retarget", user_id="u-park")
    db_session.add(project)
    await db_session.commit()
    await db_session.refresh(project)

    task = Task(
        project_id=project.id,
        payloads=[{"type": "create", "prompt": "test park path"}],
        vm_instance_id="agent-vm-park-me",
        status=TaskStatus.IN_PROGRESS,
        context={
            "llm_account_id": failed_account_id,
            "llm_model": "claude-sonnet-4-6",
        },
        attempt_count=0,
    )
    db_session.add(task)
    await db_session.commit()
    await db_session.refresh(task)

    token = create_agent_token(str(task.id), "agent-vm-park-me")
    resp = await client.post(
        "/api/agent/status",
        json={
            "task_id": str(task.id),
            "status": "FAILED",
            "failure_category": "rate_limited",
            "logs": "API Error: Rate limit reached",
        },
        headers={"x-agent-token": token},
    )
    assert resp.status_code == 200, resp.text
    body = resp.json()
    assert body["status"] == "accepted"
    assert body["action"] == "park"
    assert body["retry_after_until"]
    assert body["park_deadline"]

    await db_session.refresh(task)
    ctx = task.context or {}
    assert task.status == TaskStatus.QUEUED
    assert task.vm_instance_id == "agent-vm-park-me"
    assert task.attempt_count == 0
    # The park disposition is one of the five non-terminal branches that used
    # to overwrite the composed message with a bare state. It still LEADS (an
    # operator scanning the queue must see "parked, not abandoned" first), but
    # the agent's own report from THIS request is no longer discarded behind
    # it. Updated deliberately: the previous exact-equality value encoded the
    # clobbering defect, not the intended contract.
    assert task.latest_status_message == (
        "Rate Limited — parked on warm VM for alternate-account retarget: "
        "rate_limited — API Error: Rate limit reached"
    )
    assert ctx.get("parked_for_retarget") is True
    assert ctx.get("warm_target_vm_id") == "agent-vm-park-me"
    assert ctx.get("warm_handoff_deadline") == ctx.get("park_deadline")
    assert failed_account_id in (ctx.get("blacklisted_accounts") or [])
    assert task.retry_after_until is not None
    delete_vm.assert_not_awaited()


